function normalizeState(saved){const s=saved&&typeof saved==='object'&&!Array.isArray(saved)?saved:{};return {...defaultState,...s,tasks:Array.isArray(s.tasks)?s.tasks:[],favorites:Array.isArray(s.favorites)?s.favorites:[],seen:Array.isArray(s.seen)?s.seen:[],goals:Array.isArray(s.goals)?s.goals:[],learningDone:Array.isArray(s.learningDone)?s.learningDone:[],wellnessLog:s.wellnessLog&&typeof s.wellnessLog==='object'&&!Array.isArray(s.wellnessLog)?s.wellnessLog:{},habitLog:normalizeHabitLog(s.habitLog),reminderSettings:s.reminderSettings&&typeof s.reminderSettings==='object'?{enabled:s.reminderSettings.enabled===true,intervalMinutes:[60,120,180].includes(Number(s.reminderSettings.intervalMinutes))?Number(s.reminderSettings.intervalMinutes):120,lastReminderAt:Math.max(0,Number(s.reminderSettings.lastReminderAt)||0)}:{...defaultState.reminderSettings},reflection:s.reflection&&typeof s.reflection==='object'?{good:'',learn:'',next:'',...s.reflection}:{good:'',learn:'',next:''}}}
function readLocal(key){try{return window.NexoStore?window.NexoStore.read(key):localStorage.getItem(key)}catch{return null}}
function writeLocal(key,value){try{return window.NexoStore?window.NexoStore.write(key,String(value)):((localStorage.setItem(key,String(value))),true)}catch{return false}}
function removeLocal(key){try{if(window.NexoStore)window.NexoStore.remove(key);else{localStorage.removeItem(key);localStorage.removeItem(key+'::backup')}}catch{}}
function loadState(){try{return normalizeState(JSON.parse(readLocal(STORE)||'{}'))}catch{return normalizeState({})}}
let hasSavedSinceBoot=false;
function normalizeHabitLog(value){if(!value||typeof value!=='object'||Array.isArray(value))return{};const entries=Object.entries(value).filter(([key,row])=>/^\d{4}-\d{2}-\d{2}$/.test(key)&&row&&typeof row==='object'&&!Array.isArray(row)).sort((a,b)=>a[0].localeCompare(b[0])).slice(-180);return Object.fromEntries(entries.map(([key,row])=>[key,{focusSessions:Math.max(0,Math.min(1000,Math.floor(Number(row.focusSessions)||0))),tasksCompleted:Math.max(0,Math.min(1000,Math.floor(Number(row.tasksCompleted)||0))),wellnessCheckin:row.wellnessCheckin===true,learningModules:Math.max(0,Math.min(1000,Math.floor(Number(row.learningModules)||0)))}]))}
function save(){try{const ok=writeLocal(STORE,JSON.stringify(state));if(!ok){notify('No se pudo guardar en este dispositivo. Descargá una copia JSON desde Ajustes.');return false}hasSavedSinceBoot=true;return true}catch{notify('No se pudo guardar. Descargá una copia JSON desde Ajustes.');return false}}
function initializeResilientStorage(){const store=window.NexoStore;if(!store)return;if(store.requestPersistent)store.requestPersistent().catch(()=>false);if(store.read(STORE))return;store.restoreAll('nexo').then(records=>{if(hasSavedSinceBoot||store.read(STORE)||!Array.isArray(records)||!records.length)return;records.forEach(item=>{if(item&&typeof item.key==='string'&&typeof item.value==='string'&&!store.read(item.key))store.write(item.key,item.value)});const recovered=store.read(STORE);if(!recovered)return;try{state=normalizeState(JSON.parse(recovered));setTheme();updateStats();setView(currentView);notify('Recuperamos una copia local de tus datos.')}catch{}}).catch(()=>{})}
function notify(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
