function updateStats(){document.querySelector('#stat-tasks').textContent=state.tasks.filter(t=>t.done).length;document.querySelector('#stat-favorites').textContent=state.favorites.length;document.querySelector('#stat-points').textContent=state.points}
function setView(view){if(currentView==='neural'&&view!=='neural')disposeNeuralExperience();if(currentView==='progreso'&&view!=='progreso'){stopTimer();stopAmbientSound()}currentView=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const titles={inicio:'Un poco de todo. A tu manera.',crear:'Las ideas no aparecen solas. Probemos.',descubrir:'Siempre hay algo que no sabías.',jugar:'A ver qué tan lejos llegás.',progreso:'Tu progreso, a tu manera.',agenda:'Tu espacio para organizarte.',bienestar:'Cuidarte también cuenta.',aprender:'Aprendé algo que te sirva.',neural:'Bajá el ruido. Volvé a vos.',ajustes:'Tus datos, tus decisiones.',ruta:'Compañero de Ruta',comunidad:'Comunidad segura'};title.textContent=titles[view]||titles.inicio;if(view==='inicio')renderHome();if(view==='crear')renderCreate();if(view==='descubrir')renderDiscover();if(view==='jugar')renderGames();if(view==='progreso')renderProgress();if(view==='agenda')renderAgenda();if(view==='bienestar')renderWellbeing();if(view==='aprender')renderLearning();if(view==='neural')renderNeural();if(view==='ajustes')renderSettings();if(view==='ruta')renderCompanionRoute();if(view==='comunidad')window.NexoCommunity?.renderHub();window.scrollTo({top:0,behavior:'smooth'})}


const learningPaths=[{id:'web',title:'Cómo funciona la web',level:'Inicial',desc:'De una página vacía a una web interactiva.',modules:[['web1','HTML: estructura y semántica','Identificá encabezados, párrafos, enlaces, formularios y secciones.'],['web2','CSS: diseño y adaptación','Entendé selectores, variables, flexbox, grid y diseño responsive.'],['web3','JavaScript: interacción','Conectá eventos, estado y cambios en la interfaz.']]},{id:'science',title:'Pensamiento científico',level:'Exploración',desc:'Preguntar, observar y separar evidencia de intuición.',modules:[['sci1','Armar una buena pregunta','Convertí una curiosidad amplia en una pregunta que puedas investigar.'],['sci2','Hipótesis y evidencia','Anotá qué esperarías observar y qué datos podrían contradecirte.'],['sci3','Fuentes confiables','Compará autoría, fecha, evidencia y posibles conflictos de interés.']]},{id:'creative',title:'Creatividad práctica',level:'Todos los niveles',desc:'Generar opciones, prototipar y mejorar ideas.',modules:[['cre1','Lluvia de ideas sin filtro','Escribí diez opciones antes de juzgar cuál es mejor.'],['cre2','Prototipo rápido','Representá la idea con un dibujo, esquema o versión mínima.'],['cre3','Iterar con feedback','Elegí una mejora concreta y probá de nuevo.']]},{id:'study',title:'Estudio con estrategia',level:'Inicial',desc:'Organizar sesiones cortas y comprobar qué entendiste.',modules:[['stu1','Recuerdo activo','Cerrá el material e intentá explicar el tema con tus palabras.'],['stu2','Repaso espaciado','Volvé a una idea en distintos días en lugar de hacer todo de una vez.'],['stu3','Explicar para aprender','Enseñá el concepto como si se lo contaras a alguien que recién empieza.']]}];
function renderLearning(){const done=Array.isArray(state.learningDone)?state.learningDone:[];const total=learningPaths.reduce((n,p)=>n+p.modules.length,0);viewRoot.innerHTML='<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 06 / LABORATORIO DE APRENDIZAJE</p><h2>Aprendé por curiosidad.<br>Avanzá por partes.</h2><p>Rutas cortas con conceptos, pequeñas actividades y progreso guardado. No hay examen ni racha: podés seguir cuando quieras.</p></div><span class="agenda-date">'+done.length+' / '+total+' módulos</span></div><div class="tool-panel learning-overview"><div><p class="section-label">TU MAPA DE APRENDIZAJE</p><h3>'+Math.round(done.length/total*100)+'% explorado</h3><p class="muted">Cada módulo marcado se guarda en este navegador y suma 2 puntos. Podés desmarcarlo si querés revisar el tema otra vez.</p></div><div class="progress-track"><div class="progress-fill" style="width:'+(done.length/total*100)+'%"></div></div></div><div class="learning-grid">'+learningPaths.map(p=>'<article class="tool-panel learning-path"><div class="learning-path-top"><span class="pill-button">'+p.level+'</span><span class="learning-count">'+p.modules.filter(m=>done.includes(m[0])).length+' / '+p.modules.length+'</span></div><h3>'+p.title+'</h3><p class="muted learning-desc">'+p.desc+'</p><div class="learning-modules">'+p.modules.map(m=>'<label class="learning-module"><input type="checkbox" data-learning-module="'+m[0]+'" '+(done.includes(m[0])?'checked':'')+'><span><strong>'+m[1]+'</strong><small>'+m[2]+'</small></span></label>').join('')+'</div></article>').join('')+'</div><div class="tool-panel learning-footer"><div><p class="section-label">SIN PRESIÓN</p><h3>Una ruta también se puede retomar.</h3><p class="muted">Elegí un módulo, probalo con algo real y volvé después para marcarlo como completado.</p></div><button class="btn btn-outline" data-action="learning-reset">Reiniciar progreso de aprendizaje</button></div></section>'}
function resetLearning(){if(!confirm('¿Reiniciar los módulos completados? Esto no borra tus otros datos de NEXO.'))return;state.learningDone=[];save();renderLearning();notify('Progreso de aprendizaje reiniciado')}
function todayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function currentWellness(create=false){state.wellnessLog=state.wellnessLog&&typeof state.wellnessLog==='object'?state.wellnessLog:{};const key=todayKey();if(!state.wellnessLog[key]&&create)state.wellnessLog[key]={water:0,movement:0,sleep:'',mood:'3',energy:'3',outside:false,stretch:false,breaks:false,note:''};return state.wellnessLog[key]||{water:0,movement:0,sleep:'',mood:'3',energy:'3',outside:false,stretch:false,breaks:false,note:''}}
function getHabitDay(dateKey=todayKey()){state.habitLog=normalizeHabitLog(state.habitLog);if(!state.habitLog[dateKey])state.habitLog[dateKey]={focusSessions:0,tasksCompleted:0,wellnessCheckin:false,learningModules:0};return state.habitLog[dateKey]}
function recordGentleHabit(kind){const day=getHabitDay();if(kind==='focus')day.focusSessions=Math.min(1000,day.focusSessions+1);else if(kind==='task')day.tasksCompleted=Math.min(1000,day.tasksCompleted+1);else if(kind==='wellness')day.wellnessCheckin=true;else if(kind==='learning')day.learningModules=Math.min(1000,day.learningModules+1)}
function rhythmDataForDay(dateKey){const row=state.habitLog?.[dateKey]||{},wellness=state.wellnessLog?.[dateKey],legacyCheckin=Boolean(wellness&&(String(wellness.note||'').trim()||String(wellness.sleep||'')!==''||Number(wellness.mood||3)!==3||Number(wellness.energy||3)!==3||wellness.outside||wellness.stretch||wellness.breaks)),hasCheckin=row.wellnessCheckin===true||legacyCheckin;return{focusSessions:Math.max(0,Number(row.focusSessions)||0),tasksCompleted:Math.max(0,Number(row.tasksCompleted)||0),learningModules:Math.max(0,Number(row.learningModules)||0),wellnessCheckin:hasCheckin,mood:hasCheckin&&wellness&&Number(wellness.mood)>=1&&Number(wellness.mood)<=5?Number(wellness.mood):null,energy:hasCheckin&&wellness&&Number(wellness.energy)>=1&&Number(wellness.energy)<=5?Number(wellness.energy):null}}
function lastSevenLocalDays(){const rows=[];for(let offset=6;offset>=0;offset--){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-offset);const key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');rows.push({key,label:d.toLocaleDateString('es-AR',{weekday:'short'}),dateLabel:d.toLocaleDateString('es-AR',{day:'numeric',month:'short'}),data:rhythmDataForDay(key)})}return rows}
function renderGentleRhythm(){const days=lastSevenLocalDays(),active=days.filter(d=>d.data.focusSessions+d.data.tasksCompleted+d.data.learningModules>0||d.data.wellnessCheckin).length;return '<article class="tool-panel gentle-rhythm-panel"><div class="gentle-rhythm-head"><div><p class="section-label">01 / TU RITMO FLEXIBLE</p><h3>Lo que hiciste también cuenta.</h3><p class="muted">Días con algún paso registrado en los últimos siete días.</p></div><div class="rhythm-score"><strong>'+active+'<span>/7</span></strong><small>días con actividad</small></div></div><div class="gentle-week" role="list" aria-label="Actividad de los últimos siete días">'+days.map(d=>{const did=d.data.focusSessions+d.data.tasksCompleted+d.data.learningModules>0||d.data.wellnessCheckin;return '<div class="gentle-day '+(did?'has-activity':'')+'" role="listitem" aria-label="'+escapeHTML(d.dateLabel+': '+(did?'hubo actividad registrada':'sin actividad registrada'))+'"><span>'+escapeHTML(d.label)+'</span><i aria-hidden="true">'+(did?'✓':'·')+'</i><small>'+escapeHTML(d.dateLabel)+'</small></div>'}).join('')+'</div><p class="gentle-rhythm-note">No se pierde una racha ni hay días “malos”: un día sin registro solo es un día sin registro. Tus datos quedan en este dispositivo.</p></article>'}
function renderMoodProductivityInsights(){const days=lastSevenLocalDays(),maxActivity=Math.max(1,...days.map(d=>d.data.focusSessions+d.data.tasksCompleted)),hasMood=days.some(d=>d.data.mood!==null),hasActivity=days.some(d=>d.data.focusSessions+d.data.tasksCompleted>0);return '<article class="tool-panel mood-productivity-panel"><p class="section-label">06 / ÁNIMO Y ACTIVIDAD</p><h3>Observá tus propios patrones.</h3><p class="muted">Compará tu registro de ánimo con sesiones de enfoque y tareas completadas. Es una vista descriptiva, no un diagnóstico ni una prueba de causa y efecto.</p><div class="mood-productivity-legend"><span><i class="legend-mood"></i>Ánimo / 5</span><span><i class="legend-activity"></i>Actividad registrada</span></div><div class="mood-productivity-chart">'+days.map(d=>{const activity=d.data.focusSessions+d.data.tasksCompleted,mood=d.data.mood;return '<div class="mp-row"><div class="mp-date"><strong>'+escapeHTML(d.label)+'</strong><small>'+escapeHTML(d.dateLabel)+'</small></div><div class="mp-bars"><div class="mp-bar-line"><span>Ánimo</span><div class="mp-meter"><i class="mp-mood-fill" style="width:'+(mood===null?0:mood*20)+'%"></i></div><small>'+(mood===null?'—':mood+'/5')+'</small></div><div class="mp-bar-line"><span>Actividad</span><div class="mp-meter"><i class="mp-activity-fill" style="width:'+Math.round(activity/maxActivity*100)+'%"></i></div><small>'+activity+'</small></div></div></div>'}).join('')+'</div><p class="muted mp-footnote">'+(hasMood&&hasActivity?'Tus datos se registran localmente. Los días incompletos no se interpretan como resultados.':!hasMood?'Todavía no hay registros de ánimo suficientes para comparar. Cuando quieras, guardá un check-in en Bienestar.':'Todavía no hay actividad de enfoque o tareas completadas registrada para comparar.')+'</p></article>'}

function companionWeekStart(date=new Date()){const d=new Date(date);d.setHours(12,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function readCompanionWeeklyCheckin(){try{const value=JSON.parse(readLocal(COMPANION_WEEKLY_KEY)||'{}');return value&&value.weekStart===companionWeekStart()?{weekStart:value.weekStart,foodNote:String(value.foodNote||'').slice(0,320),physicalNote:String(value.physicalNote||'').slice(0,320)}:{weekStart:companionWeekStart(),foodNote:'',physicalNote:''}}catch{return{weekStart:companionWeekStart(),foodNote:'',physicalNote:''}}}
function saveCompanionWeeklyCheckin(){const foodNote=(document.querySelector('#companion-food-note')?.value||'').trim().slice(0,320),physicalNote=(document.querySelector('#companion-physical-note')?.value||'').trim().slice(0,320),saved=writeLocal(COMPANION_WEEKLY_KEY,JSON.stringify({weekStart:companionWeekStart(),foodNote,physicalNote,savedAt:new Date().toISOString()}));const status=document.querySelector('#companion-checkin-status');if(!saved){notify('No se pudo guardar en este dispositivo. Revisá el almacenamiento y probá exportar una copia.');if(status)status.textContent='No se pudo confirmar el guardado local.';return}notify('Tu check-in quedó guardado en este dispositivo. No se envió a la IA.');if(status)status.textContent='Guardado localmente · sólo se comparte si activás la casilla de consentimiento al pedir una reflexión.'}
function companionDayKey(date){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0')}
function companionWeekdayLabel(date){return date.toLocaleDateString('es-AR',{weekday:'long'})}
function collectCompanionContext(includeOptionalNotes=false){
  const days=[],now=new Date();
  const homeWater=(()=>{try{const v=JSON.parse(readLocal(WELLBEING_HOME_KEY)||'{}');return v.date===todayKey()?Number(v.water)||0:null}catch{return null}})();
  for(let offset=6;offset>=0;offset--){
    const date=new Date(now);date.setHours(12,0,0,0);date.setDate(date.getDate()-offset);
    const key=companionDayKey(date),wellbeing=state.wellnessLog&&state.wellnessLog[key]&&typeof state.wellnessLog[key]==='object'?state.wellnessLog[key]:null;
    const habit=state.habitLog&&state.habitLog[key]&&typeof state.habitLog[key]==='object'?state.habitLog[key]:{};
    const sleepRaw=wellbeing?.sleep,sleepHours=sleepRaw!==undefined&&sleepRaw!==null&&String(sleepRaw).trim()!==''?Math.max(0,Math.min(24,Number(sleepRaw)||0)):null;
    const mood=wellbeing&&Number(wellbeing.mood)>=1&&Number(wellbeing.mood)<=5?Number(wellbeing.mood):null;
    const energy=wellbeing&&Number(wellbeing.energy)>=1&&Number(wellbeing.energy)<=5?Number(wellbeing.energy):null;
    let water=wellbeing&&Number.isFinite(Number(wellbeing.water))?Math.max(0,Math.min(999,Number(wellbeing.water))):null;
    if(key===todayKey()&&homeWater!==null&&(water===null||water===0))water=homeWater;
    const record={day:companionWeekdayLabel(date),mood,energy,sleepHours,waterGlasses:water,movementMinutes:Math.max(0,Number(wellbeing?.movement)||0),tasksCompleted:Math.max(0,Number(habit.tasksCompleted)||0),focusSessions:Math.max(0,Number(habit.focusSessions)||0),learningModules:Math.max(0,Number(habit.learningModules)||0)};
    if(Object.values(record).some((v,i)=>i>0&&v!==null&&v!==0))days.push(record);
  }
  const checkin=readCompanionWeeklyCheckin();
  const context={period:'últimos siete días',days,totalTasksCompleted:days.reduce((n,d)=>n+d.tasksCompleted,0),totalFocusSessions:days.reduce((n,d)=>n+d.focusSessions,0),totalLearningModules:days.reduce((n,d)=>n+d.learningModules,0)};
  if(includeOptionalNotes){const foodNote=(document.querySelector('#companion-food-note')?.value??checkin.foodNote),physicalNote=(document.querySelector('#companion-physical-note')?.value??checkin.physicalNote);context.optionalWeeklyNotes={aboutFood:String(foodNote).trim().slice(0,320),physicalFeeling:String(physicalNote).trim().slice(0,320)}}
  return context;
}
function renderSundayRouteNudge(){return '<section class="companion-sunday-nudge"><div><span class="companion-eyebrow">DOMINGO · UN MOMENTO PARA VOS</span><h2>Tu semana no necesita una nota.</h2><p>Si te sirve, mirá lo que viviste y elegí una intención chiquita para lo que viene.</p></div><button type="button" class="btn btn-dark" data-view="ruta">Abrir mi reflejo ↗</button></section>'}
function localCompanionReflection(context,action){
  const days=Array.isArray(context.days)?context.days:[],moodDays=days.filter(d=>d.mood!==null&&d.mood!==undefined),sleeps=days.map(d=>d.sleepHours).filter(v=>Number.isFinite(v)&&v>0),waterDays=days.filter(d=>d.waterGlasses!==null&&d.waterGlasses!==undefined),notes=context.optionalWeeklyNotes||{};
  if(action==='suggestion'){
    const choices=['Esta semana, regalate dos minutos para mirar por la ventana y notar algo que antes pasaba de largo.','Elegí una tarea pequeña y probá hacer sólo el primer paso. Después decidís si seguir.','Guardate cinco minutos sin una meta: música, silencio o simplemente descansar.','Anotá una pregunta que te dé curiosidad, aunque todavía no sepas qué hacer con ella.','Cuando te acuerdes, hacé una pausa breve para cambiar de postura o estirar de forma cómoda.','Elegí algo amable que puedas pedir o compartir con alguien de confianza esta semana.'];
    const seed=Number(companionWeekStart().replace(/-/g,''))||1;return choices[seed%choices.length];
  }
  const parts=['Esta semana no es un examen y estos registros no alcanzan para contar todo lo que sos.'];
  if(days.length)parts.push('Hay algunas señales de cosas que fuiste anotando, y también espacios sin registro; ambos pueden convivir sin tener que explicarlos.');
  if(moodDays.length)parts.push('Tuviste momentos a los que les pusiste nombre en el check-in. Un número es apenas una instantánea, no una etiqueta sobre vos.');
  if(sleeps.length)parts.push('Sobre el descanso, podemos mirar lo que anotaste sin dar por hecho que sabemos qué causó cada sensación.');
  if(waterDays.length)parts.push('Los registros cotidianos sirven como pistas personales, no como metas para cumplir a la perfección.');
  if(notes.aboutFood||notes.physicalFeeling)parts.push('También dejaste una nota sobre comidas o sensaciones físicas; no hace falta juzgarla ni convertirla en una calificación.');
  parts.push('Tal vez la pregunta más útil no sea “¿lo hice perfecto?”, sino “¿qué me haría bien tener un poco más de espacio esta semana?”');
  return parts.join(' ');
}
function renderCompanionRoute(){
  const checkin=readCompanionWeeklyCheckin();let saved=null;try{saved=JSON.parse(readLocal(COMPANION_REFLECTION_KEY)||'null')}catch{}
  const sunday=new Date().getDay()===0,savedText=saved&&typeof saved.text==='string'?escapeHTML(saved.text):'Tu semana no necesita un veredicto. Cuando te venga bien, podemos mirar las pistas que vos elegiste compartir y dejar lugar para lo que no quedó registrado.';
  const savedLabel=saved&&saved.source==='ai'?'REFLEJO CON IA · GUARDADO EN ESTE DISPOSITIVO':saved&&saved.source==='local'?'REFLEJO LOCAL · PRIVADO EN ESTE DISPOSITIVO':'UN ESPEJO, NO UNA EVALUACIÓN';
  viewRoot.innerHTML='<section class="page-content companion-page"><div class="content-heading companion-page-heading"><div><p class="eyebrow">NEXO / COMPAÑERO DE RUTA</p><h2>Tu camino no tiene que ser<br><em>una línea recta.</em></h2><p>Un espacio para mirar tu semana con curiosidad, sin convertirla en una nota ni exigirte una versión perfecta de vos.</p></div><span class="agenda-date">'+(sunday?'DOMINGO · CUANDO VOS QUIERAS':'A TU RITMO')+'</span></div><div class="companion-layout"><article class="companion-mirror-card"><div class="companion-card-top"><div><span class="companion-eyebrow">DIARIO VIVO / REFLEJO SEMANAL</span><h3>Lo que esta semana te dejó.</h3></div><span class="companion-orbit-mark" aria-hidden="true">✳</span></div><p class="companion-reflection-text" id="companion-reflection-copy">'+savedText+'</p><div class="companion-reflection-meta" id="companion-reflection-meta">'+savedLabel+'</div><div class="companion-actions"><button type="button" class="btn btn-dark" data-action="companion-reflect">Escribir mi reflejo ↗</button><button type="button" class="btn btn-quiet" data-action="companion-suggestion">Sugerencia suave ✳</button></div><p class="companion-status" id="companion-status" role="status" aria-live="polite">Podés usarlo sin IA; no se envía nada hasta que lo elijas.</p></article><aside class="companion-context-card"><p class="section-label">TU CONTEXTO, TUS REGLAS</p><h3>¿Qué querés tener en cuenta?</h3><p>Estas notas son opcionales y se quedan en este navegador. No hay respuestas correctas y podés dejarlas vacías.</p><label class="field" for="companion-food-note">Algo sobre las comidas que quieras recordar <span class="muted">(opcional)</span><textarea id="companion-food-note" maxlength="320" rows="3" placeholder="Por ejemplo: cómo me sentí en las comidas o si hubo algo que disfruté…">'+escapeHTML(checkin.foodNote)+'</textarea></label><label class="field" for="companion-physical-note">¿Cómo te sentiste físicamente? <span class="muted">(opcional)</span><textarea id="companion-physical-note" maxlength="320" rows="3" placeholder="Energía, cansancio o sensaciones que quieras nombrar…">'+escapeHTML(checkin.physicalNote)+'</textarea></label><button type="button" class="btn btn-outline btn-full" data-action="companion-save-checkin">Guardar sólo en este dispositivo</button><p class="companion-status" id="companion-checkin-status" role="status" aria-live="polite">Tus notas no se comparten al guardarlas.</p><div class="companion-consent"><label><input type="checkbox" id="companion-share-consent"> <span><strong>Quiero compartir el contexto seleccionado con la IA</strong><small>Al pedir una reflexión o sugerencia, se enviarán los registros de los últimos siete días y las notas opcionales de arriba al proveedor externo de IA. Revisá lo escrito y no incluyas nombres, correos ni datos que te identifiquen. Podés dejar esta casilla apagada para mantener todo local.</small></span></label></div></aside></div><details class="companion-privacy-details"><summary>¿Qué hace y qué no hace Compañero de Ruta?</summary><p>Busca ayudarte a poner en palabras tu propia experiencia, no a diagnosticar ni evaluar tu salud. No decide qué deberías comer ni interpreta una nota como causa segura de otra sensación. Si una preocupación física o emocional persiste, hablá con una persona adulta de confianza o un profesional. No escribas nombres, direcciones ni otra información que te identifique.</p></details></section>';
}
function saveCompanionReflection(text,source,action){const clean=String(text||'').trim().slice(0,1400),record={text:clean,source:source==='ai'?'ai':'local',action:action==='suggestion'?'suggestion':'reflection',createdAt:new Date().toISOString()},stored=writeLocal(COMPANION_REFLECTION_KEY,JSON.stringify(record));const copy=document.querySelector('#companion-reflection-copy'),meta=document.querySelector('#companion-reflection-meta');if(copy)copy.textContent=clean;if(meta)meta.textContent=stored?(record.source==='ai'?'REFLEJO CON IA · GUARDADO EN ESTE DISPOSITIVO':'REFLEJO LOCAL · PRIVADO EN ESTE DISPOSITIVO'):'RESPUESTA VISIBLE, PERO NO GUARDADA';return stored}
async function requestCompanionAI(action,context){const endpoint=String(window.NEXO_COMPANION_ENDPOINT||'').trim();if(!endpoint)throw new Error('El servicio de IA todavía no está conectado.');const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action,context})});let payload={};try{payload=await response.json()}catch{}if(!response.ok)throw new Error(payload.error||'No pudimos conectar con la IA.');if(typeof payload.text!=='string'||!payload.text.trim())throw new Error('La IA no devolvió un texto utilizable.');return payload.text.trim().slice(0,1400)}
async function runCompanionAction(action){
  const button=document.querySelector(action==='suggestion'?'[data-action="companion-suggestion"]':'[data-action="companion-reflect"]'),status=document.querySelector('#companion-status');if(button)button.disabled=true;if(status)status.textContent='Preparando una respuesta tranquila…';
  const share=Boolean(document.querySelector('#companion-share-consent')?.checked),context=collectCompanionContext(share);let text='',source='local',failed=false;
  try{if(share){text=await requestCompanionAI(action,context);source='ai'}else{text=localCompanionReflection(context,action)}}catch{ text=localCompanionReflection(context,action);source='local';failed=true}
  const stored=saveCompanionReflection(text,source,action);
  if(status)status.textContent=!stored?'La respuesta aparece aquí, pero no pudimos guardarla en este dispositivo.':source==='ai'?'Listo. Se usó el contexto que elegiste compartir; la respuesta quedó guardada localmente.':failed?'No pudimos conectar con la IA; te dejamos una alternativa local. Revisá la configuración del servicio.':'Listo: creamos una respuesta local. No se enviaron tus datos a un proveedor externo.';
  if(button)button.disabled=false;
}

