function wellbeingHomeDate(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function wellbeingHomeOrdinal(key){const p=key.split('-').map(Number);return Math.floor(Date.UTC(p[0],p[1]-1,p[2])/86400000)}
function readWellbeingHome(){const today=wellbeingHomeDate();try{const saved=JSON.parse(readLocal(WELLBEING_HOME_KEY)||'{}');if(saved.date!==today)return {date:today,water:0};return {date:today,water:Math.max(0,Math.min(8,Number(saved.water)||0))}}catch{return {date:today,water:0}}}
function renderWellbeingWater(){const state=readWellbeingHome(),count=document.querySelector('#home-water-count'),label=document.querySelector('#home-water-label');document.querySelectorAll('[data-water-level]').forEach(button=>{const level=Number(button.dataset.waterLevel),filled=level<=state.water;button.classList.toggle('is-filled',filled);button.setAttribute('aria-pressed',String(filled));button.setAttribute('aria-label',(filled?'Vaso registrado '+level:'Registrar hasta '+level+' vasos'))});if(count)count.textContent=state.water;if(label)label.textContent=state.water===0?'Tocá un vaso para registrar agua.':state.water===8?'¡Listo! Registraste los 8 vasos de este contador.':state.water+' de 8 registrados · adaptalo a tus necesidades.'}
function renderWellbeingTip(){const root=document.querySelector('#home-mind-content');if(!root||!wellbeingHomeTips.length)return;const today=wellbeingHomeDate(),index=wellbeingHomeOrdinal(today)%wellbeingHomeTips.length,tip=wellbeingHomeTips[index];wellbeingHomeTipDay=today;const tag=document.querySelector('#home-mind-type');if(tag)tag.textContent=tip.type==='Receta en 3 pasos'?'RECETA RÁPIDA · 3 PASOS':'TIP DE SALUD DEL DÍA';root.innerHTML='<h3 class="home-wellbeing-tip-title">'+escapeHTML(tip.title)+'</h3>'+(Array.isArray(tip.steps)?'<ol class="home-tip-steps">'+tip.steps.map(step=>'<li>'+escapeHTML(step)+'</li>').join('')+'</ol>':'<p class="home-wellbeing-tip-body">'+escapeHTML(tip.body||'Un pequeño recordatorio para cuidarte a tu manera.')+'</p>');const footer=document.querySelector('#home-mind-footer');if(footer)footer.textContent='IDEA '+String(index+1).padStart(2,'0')+' / '+wellbeingHomeTips.length+' · CAMBIA CADA 24 H'}
function setupWellbeingHome(){const root=document.querySelector('#wellbeing-home');if(!root)return;renderWellbeingWater();root.querySelectorAll('[data-water-level]').forEach(button=>button.addEventListener('click',()=>{const level=Number(button.dataset.waterLevel),current=readWellbeingHome();current.water=level<=current.water?level-1:Math.min(8,current.water+1);try{writeLocal(WELLBEING_HOME_KEY,JSON.stringify(current))}catch{notify('No se pudo guardar el contador en este navegador.')}renderWellbeingWater()}));const reset=root.querySelector('[data-water-reset]');reset?.addEventListener('click',()=>{const current={date:wellbeingHomeDate(),water:0};try{writeLocal(WELLBEING_HOME_KEY,JSON.stringify(current))}catch{}renderWellbeingWater();notify('Contador de agua reiniciado.')});if(!wellbeingHomeTips.length){fetch('./wellbeing-tips.json').then(response=>{if(!response.ok)throw new Error('No se pudo cargar el archivo de consejos');return response.json()}).then(tips=>{if(!Array.isArray(tips)||!tips.length)throw new Error('Archivo de consejos vacío');wellbeingHomeTips=tips;renderWellbeingTip()}).catch(()=>{wellbeingHomeTips=[{type:'Tip',title:'Hacé una pausa amable',body:'Tomate un momento para revisar qué necesitás ahora: agua, descanso, movimiento suave o simplemente seguir a tu ritmo.'}];renderWellbeingTip()})}else renderWellbeingTip();if(wellbeingHomeTimer)clearInterval(wellbeingHomeTimer);wellbeingHomeTimer=setInterval(()=>{if(wellbeingHomeTipDay!==wellbeingHomeDate())renderWellbeingTip();const current=readWellbeingHome();if(current.date!==document.querySelector('#home-water-label')?.dataset.date){renderWellbeingWater();const label=document.querySelector('#home-water-label');if(label)label.dataset.date=current.date}},60000);const label=document.querySelector('#home-water-label');if(label)label.dataset.date=wellbeingHomeDate()}


