let discoveryDeckQueue=[],discoveryRepeatMode=false,discoverySwipeLocked=false,discoveryDragInteractable=null,discoveryPointerState=null;
function discoveryDailyRecord(){
 const today=todayKey();
 try{const saved=JSON.parse(readLocal(DISCOVERY_DAILY_KEY)||'null');if(saved&&saved.day===today&&Array.isArray(saved.ids))return {day:today,ids:[...new Set(saved.ids.filter(id=>discoveries.some(d=>d.id===id)))]}}catch{}
 return {day:today,ids:[]};
}
function saveDiscoveryDaily(record){try{writeLocal(DISCOVERY_DAILY_KEY,JSON.stringify({day:record.day,ids:[...new Set(record.ids)]}));return true}catch{return false}}
function shuffleDiscoveries(items){const list=items.slice();for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}
function updateDiscoveryCounter(){
 const daily=discoveryDailyRecord(),count=document.querySelector('#discovery-learned-count'),fill=document.querySelector('#discovery-progress-fill'),sub=document.querySelector('#discovery-learned-subtitle'),remaining=document.querySelector('#discovery-remaining-count');
 if(count)count.textContent=String(daily.ids.length).padStart(2,'0');
 if(fill)fill.style.width=(daily.ids.length/Math.max(1,discoveries.length)*100)+'%';
 if(sub)sub.textContent=daily.ids.length===discoveries.length?'Colección completa por hoy':'de '+discoveries.length+' curiosidades de la colección';
 if(remaining)remaining.textContent=discoveryDeckQueue.length+' por descubrir';
}
function renderDiscover(){
 const daily=discoveryDailyRecord();
 viewRoot.innerHTML='<section class="page-content discovery-experience"><div class="discovery-intro-row"><div class="discovery-intro-copy"><p class="eyebrow">MUNDO 02 / CURIOSIDAD ACTIVA</p><h2>Una idea a la vez.</h2><p>Explorá el mundo sin listas interminables. Guardá lo que te vuele la cabeza; lo demás, dejalo pasar.</p></div><div class="discovery-daily-meter" aria-live="polite"><span class="discovery-meter-label">DATOS APRENDIDOS HOY</span><div class="discovery-meter-number"><strong id="discovery-learned-count">'+String(daily.ids.length).padStart(2,'0')+'</strong><span id="discovery-learned-subtitle">'+(daily.ids.length===discoveries.length?'Colección completa por hoy':'de '+discoveries.length+' curiosidades de la colección')+'</span></div><div class="discovery-meter-track" aria-hidden="true"><i id="discovery-progress-fill" style="width:'+(daily.ids.length/Math.max(1,discoveries.length)*100)+'%"></i></div></div></div><div class="discovery-session-head"><div><span class="discovery-kicker">SCROLL DE CURIOSIDAD</span><h3>¿Qué descubrimos ahora?</h3></div><span class="discovery-swipe-instructions"><span>←</span> DESCARTAR <i></i> GUARDAR <span>→</span></span></div><div class="discovery-deck-stack" id="discovery-deck" aria-label="Mazo de curiosidades"></div><div class="discovery-action-row"><button type="button" class="discovery-action discovery-dismiss" data-action="discovery-swipe-left"><span class="discovery-action-icon">×</span><span>Descartar</span><kbd>←</kbd></button><button type="button" class="discovery-action discovery-save" data-action="discovery-swipe-right"><span class="discovery-action-icon">★</span><span>Guardar favorito</span><kbd>→</kbd></button></div><p class="discovery-gesture-hint">Deslizá la tarjeta o usá los botones. Cada gesto cuenta como un dato explorado.</p><div class="discovery-source-note"><span>18 DATOS · FUENTES DE REFERENCIA</span><span>LO INTERESANTE SE GUARDA, NO SE ACUMULA</span></div></section>';
 startDiscoveryDeck(false);
}
function startDiscoveryDeck(repeat){
 discoveryRepeatMode=Boolean(repeat);discoverySwipeLocked=false;
 const daily=discoveryDailyRecord();
 discoveryDeckQueue=shuffleDiscoveries(discoveryRepeatMode?discoveries:discoveries.filter(d=>!daily.ids.includes(d.id)));
 renderDiscoveryCards();
}
function discoveryCardMarkup(d,index,active){
 const image=DISCOVERY_IMAGES[d.id]||DISCOVERY_IMAGES.d6;
 const cls='discovery-stack-card discovery-stack-layer-'+index+(active?' discovery-card-active':'');
 const activeAttrs=active?' data-discovery-active="true" tabindex="0" role="group" aria-label="Curiosidad actual. Deslizá a la derecha para guardar o a la izquierda para descartar."':' aria-hidden="true"';
 const title=escapeHTML(d.title),fact=escapeHTML(d.text),category=escapeHTML(d.category),source=escapeHTML(d.source),url=escapeHTML(d.url);
 return '<article class="'+cls+'"'+activeAttrs+' style="--discovery-image:url(&quot;'+escapeHTML(image)+'&quot;)"><div class="discovery-card-backdrop"></div><div class="discovery-card-grain"></div><div class="discovery-card-content"><div class="discovery-card-top"><span class="discovery-category">'+category+'</span><span class="discovery-card-number">'+String(discoveries.findIndex(x=>x.id===d.id)+1).padStart(2,'0')+' <i>/ '+String(discoveries.length).padStart(2,'0')+'</i></span></div><div class="discovery-card-main"><span class="discovery-card-eyebrow">¿SABÍAS QUE…?</span><h4>'+title+'</h4><p>'+fact+'</p></div><div class="discovery-card-footer"><div><span class="discovery-source-label">FUENTE</span><strong>'+source+'</strong></div><a class="discovery-source-link" href="'+url+'" target="_blank" rel="noopener noreferrer" tabindex="'+(active?'0':'-1')+'">Comprobar ↗</a></div></div><div class="discovery-swipe-stamp discovery-stamp-save"><span>★</span> GUARDAR</div><div class="discovery-swipe-stamp discovery-stamp-dismiss"><span>×</span> DESCARTAR</div></article>';
}
function renderDiscoveryCards(){
 const root=document.querySelector('#discovery-deck');if(!root)return;
 updateDiscoveryCounter();
 if(!discoveryDeckQueue.length){
  root.innerHTML='<div class="discovery-deck-complete"><span class="discovery-complete-mark">✳</span><span class="discovery-kicker">FIN DEL RECORRIDO</span><h3>Por hoy, ya exploraste todo.</h3><p>Dejá que las ideas se acomoden. Podés volver a repasar la colección sin sumar datos repetidos al contador.</p><button type="button" class="btn btn-dark" data-action="discovery-replay">Volver a explorar ↗</button></div>';
  const controls=document.querySelectorAll('.discovery-action');controls.forEach(b=>b.disabled=true);
  const hint=document.querySelector('.discovery-gesture-hint');if(hint)hint.textContent='Colección completa. Tus favoritos siguen disponibles en Progreso.';
  return;
 }
 const controls=document.querySelectorAll('.discovery-action');controls.forEach(b=>b.disabled=false);
 const hint=document.querySelector('.discovery-gesture-hint');if(hint)hint.textContent=discoveryRepeatMode?'Modo repaso: los datos repetidos no suman otra vez al contador.':'Deslizá la tarjeta o usá los botones. Cada gesto cuenta como un dato explorado.';
 root.innerHTML=discoveryDeckQueue.slice(0,3).map((d,i)=>discoveryCardMarkup(d,i,i===0)).join('');
 setupDiscoveryDrag();
}
function setupDiscoveryDrag(){
 const card=document.querySelector('[data-discovery-active="true"]');if(!card)return;
 const threshold=()=>Math.max(90,card.getBoundingClientRect().width*.24);
 const move=(x,y)=>{
  card.dataset.dragX=String(x);card.dataset.dragY=String(y);card.style.transform='translate3d('+x+'px,'+y+'px,0) rotate('+(x*.055)+'deg)';
  const ratio=Math.min(1,Math.abs(x)/threshold());card.style.setProperty('--discovery-swipe-opacity',String(ratio));
  card.classList.toggle('show-save-stamp',x>16);card.classList.toggle('show-dismiss-stamp',x< -16);
 };
 const done=x=>{
  const distance=threshold();
  if(x>distance)resolveDiscoverySwipe('right');
  else if(x< -distance)resolveDiscoverySwipe('left');
  else{card.style.transform='';card.style.opacity='';card.style.removeProperty('--discovery-swipe-opacity');card.classList.remove('is-dragging','show-save-stamp','show-dismiss-stamp');card.dataset.dragX='0';card.dataset.dragY='0'}
 };
 if(typeof window.interact==='function'){
  try{
   discoveryDragInteractable=window.interact(card).draggable({inertia:true,allowFrom:'.discovery-card-content',ignoreFrom:'a',listeners:{
    start(event){if(discoverySwipeLocked)return;card.classList.add('is-dragging');card.dataset.dragX='0';card.dataset.dragY='0'},
    move(event){if(discoverySwipeLocked)return;const x=Number(card.dataset.dragX||0)+event.dx,y=Number(card.dataset.dragY||0)+event.dy;move(x,y)},
    end(){if(discoverySwipeLocked)return;done(Number(card.dataset.dragX||0))}
   }});
   return;
  }catch(error){discoveryDragInteractable=null}
 }
 const down=e=>{if(e.target.closest('a'))return;discoveryPointerState={id:e.pointerId,x:e.clientX,y:e.clientY,lastX:0,lastY:0};card.setPointerCapture?.(e.pointerId);card.classList.add('is-dragging')};
 const pointerMove=e=>{if(!discoveryPointerState||e.pointerId!==discoveryPointerState.id)return;const x=e.clientX-discoveryPointerState.x,y=e.clientY-discoveryPointerState.y;discoveryPointerState.lastX=x;discoveryPointerState.lastY=y;if(Math.abs(x)>8)move(x,y)};
 const up=e=>{if(!discoveryPointerState||e.pointerId!==discoveryPointerState.id)return;const x=discoveryPointerState.lastX;discoveryPointerState=null;done(x)};
 card.addEventListener('pointerdown',down);card.addEventListener('pointermove',pointerMove);card.addEventListener('pointerup',up);card.addEventListener('pointercancel',up);
}
function resolveDiscoverySwipe(direction){
 if(discoverySwipeLocked||!discoveryDeckQueue.length)return;
 discoverySwipeLocked=true;
 const fact=discoveryDeckQueue.shift(),card=document.querySelector('[data-discovery-active="true"]');
 if(discoveryDragInteractable){try{discoveryDragInteractable.unset()}catch{}discoveryDragInteractable=null}
 if(card){
  card.classList.remove('is-dragging');card.classList.add(direction==='right'?'is-swipe-right':'is-swipe-left');
  card.style.transform='';card.style.setProperty('--discovery-swipe-opacity','1');
  card.querySelectorAll('a').forEach(a=>a.tabIndex=-1);
 }
 if(direction==='right'&&!state.favorites.includes(fact.id))state.favorites=[...state.favorites,fact.id];
 if(!state.seen.includes(fact.id))state.seen=[...state.seen,fact.id];
 save();
 if(!discoveryRepeatMode){const daily=discoveryDailyRecord();if(!daily.ids.includes(fact.id)){daily.ids.push(fact.id);saveDiscoveryDaily(daily)}}
 updateStats();updateDiscoveryCounter();
 const hint=document.querySelector('.discovery-gesture-hint');if(hint)hint.textContent=direction==='right'?'Guardado en Favoritos. Siguiente curiosidad…':'Descartado. Siguiente curiosidad…';
 window.setTimeout(()=>{discoverySwipeLocked=false;if(currentView==='descubrir')renderDiscoveryCards()},260);
}
function renderDiscoveryList(){renderDiscoveryCards()}
function swipeDiscoveryByAction(direction){resolveDiscoverySwipe(direction)}

function loadReflexScores(){try{const list=JSON.parse(readLocal(REFLEX_STORAGE_KEY)||'[]');return Array.isArray(list)?list.filter(n=>Number.isFinite(n)&&n>0).sort((a,b)=>a-b).slice(0,3):[]}catch{return []}}
function saveReflexScores(){try{writeLocal(REFLEX_STORAGE_KEY,JSON.stringify(reflexTimes))}catch{notify('No se pudo guardar el récord en este navegador.')}}
function renderReflexScores(){const list=document.querySelector('#reflex-scores');if(!list)return;list.innerHTML=reflexTimes.length?reflexTimes.map((time,index)=>'<li class="reflex-score-row"><span class="reflex-rank">'+['01','02','03'][index]+'</span><strong>'+time+'</strong><span>ms</span>'+(index===0?'<span class="reflex-crown">★</span>':'')+'</li>').join(''):'<li class="reflex-empty">Todavía no hay marcas. ¡Hacé la primera!</li>'}
function setReflexStatus(phase){const target=document.querySelector('#reflex-target'),word=document.querySelector('#reflex-target-word'),status=document.querySelector('#reflex-status'),message=document.querySelector('#reflex-message'),start=document.querySelector('#reflex-start'),again=document.querySelector('#reflex-again');if(!target)return;reflexPhase=phase;target.classList.remove('reflex-target-idle','reflex-target-waiting','reflex-target-go','reflex-target-early','reflex-target-result');target.classList.add(({idle:'reflex-target-idle',waiting:'reflex-target-waiting',go:'reflex-target-go',early:'reflex-target-early',result:'reflex-target-result'})[phase]||'reflex-target-idle');target.disabled=phase==='idle'||phase==='result';target.setAttribute('aria-label',phase==='go'?'¡Verde! Tocá ahora':phase==='waiting'?'Esperá a que el círculo se ponga verde':'Objetivo de reflejos');if(word)word.textContent=({idle:'LISTO',waiting:'ESPERÁ',go:'¡YA!',early:'¡UPS!',result:'FIN'})[phase]||'LISTO';if(status)status.textContent=({idle:'PREPARADO',waiting:'ESPERANDO SEÑAL',go:'¡AHORA!',early:'SALIDA EN FALSO',result:'RONDA TERMINADA'})[phase]||'PREPARADO';if(start)start.hidden=phase==='waiting'||phase==='go';if(again)again.hidden=phase!=='result'&&phase!=='early';if(phase==='idle'&&message)message.textContent='Presioná empezar y esperá la señal verde.'}
function stopReflexTimers(){if(reflexTimeout)clearTimeout(reflexTimeout);if(reflexTimer)clearTimeout(reflexTimer);reflexTimeout=reflexTimer=null}
function startReflexRound(){if(!document.querySelector('#reflex-game'))return;stopReflexTimers();const time=document.querySelector('#reflex-time'),message=document.querySelector('#reflex-message');if(time)time.innerHTML='—<small> ms</small>';if(message)message.textContent='No te adelantes. Tocá únicamente cuando aparezca el verde.';setReflexStatus('waiting');reflexTimer=setTimeout(()=>{if(reflexPhase!=='waiting')return;reflexStartedAt=performance.now();setReflexStatus('go');if(message)message.textContent='¡Ahora! Tocá el círculo.'},1500+Math.random()*4500)}
function burstReflexConfetti(){const host=document.querySelector('#reflex-card');if(!host)return;const layer=document.createElement('div');layer.className='reflex-confetti';layer.setAttribute('aria-hidden','true');for(let i=0;i<24;i++){const piece=document.createElement('i');piece.style.setProperty('--confetti-x',(Math.random()*240-120)+'px');piece.style.setProperty('--confetti-y',(-35-Math.random()*125)+'px');piece.style.setProperty('--confetti-rotate',(Math.random()*600-300)+'deg');piece.style.setProperty('--confetti-delay',(Math.random()*.2)+'s');layer.appendChild(piece)}host.appendChild(layer);setTimeout(()=>layer.remove(),1400)}
function handleReflexTap(){if(reflexPhase==='waiting'){stopReflexTimers();setReflexStatus('early');const time=document.querySelector('#reflex-time'),message=document.querySelector('#reflex-message');if(time)time.innerHTML='—<small> ms</small>';if(message)message.innerHTML='<span class="reflex-too-fast">¡Demasiado rápido!</span> Esperá a que el círculo se ponga verde.';const target=document.querySelector('#reflex-target');if(target){target.classList.add('reflex-shake');setTimeout(()=>target.classList.remove('reflex-shake'),350)}if(navigator.vibrate)try{navigator.vibrate(80)}catch{}return}if(reflexPhase!=='go')return;const elapsed=Math.max(0,Math.round(performance.now()-reflexStartedAt));stopReflexTimers();setReflexStatus('result');const time=document.querySelector('#reflex-time'),message=document.querySelector('#reflex-message');if(time)time.innerHTML=elapsed+'<small> ms</small>';const previous=reflexTimes.slice();reflexTimes=[...reflexTimes,elapsed].sort((a,b)=>a-b).slice(0,3);const isRecord=!previous.length||elapsed<previous[0];if(message)message.textContent=elapsed<220?'¡Reflejos rapidísimos!':elapsed<320?'¡Muy buena reacción!':'¡Bien jugado! Probá otra vez para mejorar.';if(isRecord){saveReflexScores();burstReflexConfetti();if(navigator.vibrate)try{navigator.vibrate([35,45,70])}catch{}if(message)message.textContent='¡Nuevo récord personal! '+elapsed+' ms. ¡Excelente reflejo!'}renderReflexScores()}
function setupReflexGame(){reflexTimes=loadReflexScores();renderReflexScores()}

function renderGames(){viewRoot.innerHTML=`<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 03 / JUEGO LIMPIO</p><h2>Probá lo que sabés.<br>Descubrí lo que falta.</h2><p>Partidas individuales, puntuación local y explicaciones para aprender jugando.</p></div></div><div class="world-grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))"><article class="tool-panel"><p class="section-label">JUEGO 01 / TRIVIA</p><h3 style="font:800 25px Manrope">Mente curiosa</h3><p class="muted" style="line-height:1.7">Ocho preguntas, cuatro opciones y una explicación después de cada respuesta.</p><div class="stats-row"><div><strong>08</strong><span>preguntas</span></div><div><strong id="quiz-best">\${state.quizBest}</strong><span>mejor puntaje</span></div><div><strong>∞</strong><span>revancha</span></div></div><button class="btn btn-dark" data-action="start-quiz">Empezar trivia ↗</button><div id="quiz-area" style="margin-top:18px"></div></article><article class="tool-panel"><p class="section-label">JUEGO 02 / PALABRAS</p><h3 style="font:800 25px Manrope">La palabra escondida</h3><p class="muted" style="line-height:1.7">Descubrí una palabra con pistas. Cada intento cuenta; podés pedir una pista adicional.</p><div id="word-area"><div class="result-box">¿Te animás a resolverla?</div><button class="btn btn-outline" style="margin-top:13px" data-action="start-word">Jugar ahora ↗</button></div></article><article class="tool-panel reflex-card" id="reflex-card"><button class="reflex-expand-toggle" type="button" data-action="toggle-reflex" aria-expanded="false" aria-controls="reflex-game"><span><span class="section-label">JUEGO 03 / VELOCIDAD</span><strong>Reflejos Ninja</strong><small>¿Qué tan rápido reaccionás?</small></span><span class="reflex-expand-icon" aria-hidden="true">＋</span></button><div class="reflex-game" id="reflex-game" hidden><div class="reflex-game-head"><span class="reflex-status-pill" id="reflex-status">PREPARADO</span><span class="reflex-round">TOCÁ CUANDO SE PONGA VERDE</span></div><button type="button" class="reflex-target reflex-target-idle" id="reflex-target" data-action="reflex-target" aria-label="Objetivo de reflejos. Iniciá una ronda primero"><span class="reflex-target-core"></span><span class="reflex-target-word" id="reflex-target-word">LISTO</span></button><div class="reflex-result" aria-live="polite"><strong id="reflex-time">—<small> ms</small></strong><p id="reflex-message">Presioná empezar y esperá la señal verde.</p></div><div class="reflex-actions"><button class="btn btn-dark" id="reflex-start" type="button" data-action="reflex-start">Empezar ronda ↗</button><button class="btn btn-quiet" id="reflex-again" type="button" data-action="reflex-start" hidden>Otra vez</button></div><div class="reflex-leaderboard"><div class="reflex-board-heading"><div><p class="section-label">TU PODIO LOCAL</p><h4>Top 3 mejores tiempos</h4></div><span>MENOS MS = MEJOR</span></div><ol id="reflex-scores" class="reflex-scores"><li class="reflex-empty">Todavía no hay marcas. ¡Hacé la primera!</li></ol><p class="reflex-local-note">Récords guardados solo en este navegador.</p></div></div></article></div></section>`}
function startQuiz(){quiz={questions:[...quizQuestions].sort(()=>Math.random()-.5).slice(0,5),index:0,score:0,answered:false};renderQuizQuestion()}
function renderQuizQuestion(){const root=document.querySelector('#quiz-area');if(!root||!quiz)return;if(quiz.index>=quiz.questions.length){state.quizBest=Math.max(state.quizBest,quiz.score);state.points+=quiz.score*5;save();updateStats();root.innerHTML=`<div class="result-box"><p class="section-label">RONDA TERMINADA</p><h3 style="font:800 25px Manrope">${quiz.score} de ${quiz.questions.length}</h3><p>${quiz.score===5?'¡Impecable!':quiz.score>=3?'¡Buen trabajo!':'Cada pregunta suma experiencia.'} ${quiz.score*5} puntos ganados.</p><div class="progress-track"><div class="progress-fill" style="width:${quiz.score/quiz.questions.length*100}%"></div></div><button class="btn btn-dark" style="margin-top:16px" data-action="start-quiz">Jugar otra vez ↗</button></div>`;return}const q=quiz.questions[quiz.index];root.innerHTML=`<p class="section-label">PREGUNTA ${quiz.index+1} / ${quiz.questions.length} · PUNTOS ${quiz.score}</p><div class="progress-track"><div class="progress-fill" style="width:${quiz.index/quiz.questions.length*100}%"></div></div><h3 style="font:700 18px/1.45 Manrope;margin:18px 0 10px">${escapeHTML(q.q)}</h3><div>${q.options.map((o,i)=>`<button type="button" class="quiz-option" data-answer="${i}"><span class="quiz-option-label">${escapeHTML(o)}</span></button>`).join('')}</div><div id="quiz-feedback"></div>`;root.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{if(quiz.answered)return;quiz.answered=true;const correct=Number(b.dataset.answer)===q.correct;if(correct)quiz.score++;root.querySelectorAll('[data-answer]').forEach(btn=>{btn.disabled=true;if(Number(btn.dataset.answer)===q.correct)btn.classList.add('correct')});if(!correct)b.classList.add('wrong');document.querySelector('#quiz-feedback').innerHTML=`<div class="result-box" style="margin-top:13px"><strong>${correct?'¡Correcto!':'No era esa, y está bien.'}</strong><p style="font-size:12px;margin:7px 0 0">${escapeHTML(q.explain)}</p><button class="btn btn-dark" style="margin-top:12px" data-action="next-question">${quiz.index===quiz.questions.length-1?'Ver resultado':'Siguiente pregunta'} →</button></div>`;document.querySelector('[data-action="next-question"]').addEventListener('click',()=>{quiz.index++;quiz.answered=false;renderQuizQuestion()})}))}
const wordBank=[{word:'PLANETA',hint:'Un cuerpo celeste que orbita una estrella.',extra:'La Tierra es uno de ellos.'},{word:'BRUJULA',hint:'Ayuda a orientarse usando el campo magnético terrestre.',extra:'Su aguja señala aproximadamente el norte magnético.'},{word:'TECLADO',hint:'Lo usás para escribir en una computadora.',extra:'Puede ser mecánico o de membrana.'},{word:'BOSQUE',hint:'Ecosistema donde predominan los árboles.',extra:'Puede albergar una enorme biodiversidad.'}];
function startWord(){const item=wordBank[Math.floor(Math.random()*wordBank.length)];wordRound={item,tries:0,usedHint:false};renderWord()}
function renderWord(){const root=document.querySelector('#word-area');if(!root||!wordRound)return;root.innerHTML=`<p class="section-label">PISTA ${wordRound.usedHint?2:1} · INTENTOS ${wordRound.tries}</p><div class="result-box">${escapeHTML(wordRound.item.hint)}<p id="word-extra" style="margin:8px 0 0">${wordRound.usedHint?escapeHTML(wordRound.item.extra):''}</p></div><form id="word-form" style="margin-top:14px"><label class="field">Tu respuesta<input id="word-answer" class="game-answer-input" autocomplete="off" maxlength="30" required placeholder="Escribí una palabra..." aria-describedby="word-feedback"></label><div class="button-row"><button class="btn btn-dark">Probar respuesta ↗</button><button type="button" class="btn btn-quiet" id="word-hint">Otra pista</button></div></form><div id="word-feedback" class="game-answer-feedback" role="status" aria-live="polite"></div>`;document.querySelector('#word-hint').addEventListener('click',()=>{wordRound.usedHint=true;renderWord()});document.querySelector('#word-answer').addEventListener('input',()=>{const input=document.querySelector('#word-answer'),feedback=document.querySelector('#word-feedback');input.classList.remove('answer-input-correct','answer-input-wrong');input.removeAttribute('aria-invalid');feedback.textContent='';feedback.className='game-answer-feedback'});document.querySelector('#word-form').addEventListener('submit',e=>{e.preventDefault();const val=document.querySelector('#word-answer').value.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();wordRound.tries++;if(val===wordRound.item.word){const pts=Math.max(5,20-wordRound.tries*3-(wordRound.usedHint?5:0));state.points+=pts;state.wordBest=Math.max(state.wordBest,pts);save();updateStats();const answerInput=document.querySelector('#word-answer'),answerForm=document.querySelector('#word-form');answerInput.classList.remove('answer-input-wrong');void answerInput.offsetWidth;answerInput.classList.add('answer-input-correct');answerInput.setAttribute('aria-invalid','false');answerInput.disabled=true;answerForm.querySelector('button:not([type]),button[type="submit"]') .disabled=true;document.querySelector('#word-feedback').className='game-answer-feedback game-answer-feedback-correct';document.querySelector('#word-feedback').innerHTML=`<div class="result-box game-answer-result game-answer-result-correct" style="margin-top:12px"><strong>¡La encontraste! +${pts} puntos</strong><p>La palabra era ${escapeHTML(wordRound.item.word)}.</p><button type="button" class="btn btn-dark" id="word-again">Otra palabra ↗</button></div>`;const completedForm=answerForm;window.setTimeout(()=>{if(completedForm.isConnected)completedForm.remove()},620);document.querySelector('#word-again').addEventListener('click',startWord)}else{const answerInput=document.querySelector('#word-answer');answerInput.classList.remove('answer-input-correct','answer-input-wrong');void answerInput.offsetWidth;answerInput.classList.add('answer-input-wrong');answerInput.setAttribute('aria-invalid','true');document.querySelector('#word-feedback').className='game-answer-feedback game-answer-feedback-wrong';document.querySelector('#word-feedback').innerHTML=`<p class="game-inline-feedback" role="status">${wordRound.tries>=5?'Pista: la palabra tiene '+wordRound.item.word.length+' letras.':'Todavía no. Probá otra vez, ¡vas bien!'}</p>`}})}
function renderProgress(){const total=state.tasks.length,done=state.tasks.filter(t=>t.done).length;viewRoot.innerHTML=`<section class="page-content"><div class="content-heading"><div><p class="eyebrow">MUNDO 04 / TU ESPACIO</p><h2>Avanzar también es<br>ir a tu ritmo.</h2><p>Una lista clara para sacar cosas de la cabeza y llevarlas al día. Sin rachas obligatorias ni culpa por cambiar de plan.</p></div></div>${renderGentleRhythm()}<div class="world-grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr));align-items:start"><article class="tool-panel"><p class="section-label">01 / LISTA DE TAREAS</p><form id="task-form"><label class="field">¿Qué querés hacer?<input id="task-title" maxlength="120" required placeholder="Ej. Leer un capítulo, ordenar el escritorio..."></label><div class="form-grid" style="margin-top:12px"><label class="field">Fecha (opcional)<input id="task-date" type="date"></label><label class="field">Tipo<select id="task-type"><option>Personal</option><option>Estudio</option><option>Proyecto</option><option>Descanso</option></select></label></div><button class="btn btn-dark" style="margin-top:13px">Agregar tarea +</button></form><div class="button-row"><button class="pill-button active" data-task-filter="all">Todas</button><button class="pill-button" data-task-filter="open">Pendientes</button><button class="pill-button" data-task-filter="done">Completadas</button></div><div id="task-list" class="item-list" style="margin-top:14px"></div><div style="margin-top:17px"><div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:8px"><span>Tu avance</span><strong>${done}/${total}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${total?done/total*100:0}%"></div></div></div></article><article class="tool-panel focus-station-card" id="focus-station-card"><p class="section-label">02 / ESTACIÓN DE ENFOQUE</p><div class="focus-station-heading"><div><h3>Un bloque. Una cosa.</h3><p>Reducí el ruido externo. No tenés que resolverlo todo ahora.</p></div><span class="focus-station-chip"><i></i> 25 MIN / FOCUS</span></div><div class="focus-station-layout"><div class="focus-clock-column"><div class="focus-clock-shell" id="focus-clock-shell" role="progressbar" aria-label="Tiempo de enfoque restante" aria-valuemin="0" aria-valuemax="100" aria-valuenow="100" aria-valuetext="25 minutos restantes"><svg class="focus-clock-svg" viewBox="0 0 220 220" aria-hidden="true"><defs><linearGradient id="focus-ring-gradient" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#b9f5d8"/><stop offset="100%" stop-color="#65b99b"/></linearGradient></defs><circle class="focus-clock-track" cx="110" cy="110" r="86" fill="none" stroke-width="5"/><circle class="focus-clock-progress" id="timer-ring-progress" cx="110" cy="110" r="86" fill="none" stroke="url(#focus-ring-gradient)" stroke-width="5" stroke-linecap="round" stroke-dasharray="540.35" stroke-dashoffset="0" transform="rotate(-90 110 110)"/></svg><div class="focus-clock-center"><strong id="timer-display">25:00</strong><span id="focus-clock-caption">UN BLOQUE PARA VOS</span></div><span class="focus-clock-orbit focus-clock-orbit-a"></span><span class="focus-clock-orbit focus-clock-orbit-b"></span></div><p id="timer-status" class="focus-timer-status">LISTO CUANDO VOS ESTÉS</p><label class="field focus-duration-field">Duración del bloque<select id="timer-duration"><option value="15">15 minutos</option><option value="25" selected>25 minutos · Pomodoro</option><option value="45">45 minutos</option><option value="5">5 minutos · Prueba</option></select></label><div class="focus-timer-actions"><button class="btn btn-dark" id="timer-start" type="button">Empezar</button><button class="btn btn-quiet" id="timer-reset" type="button" aria-label="Reiniciar temporizador">↺ Reiniciar</button></div><button type="button" class="focus-sound-toggle" id="focus-sound-toggle" data-action="toggle-focus-sounds" aria-expanded="false" aria-controls="focus-sound-panel"><span class="focus-sound-toggle-icon">♫</span><span class="focus-sound-toggle-label">Abrir paisaje sonoro</span><span class="focus-sound-toggle-arrow">＋</span></button></div><aside class="focus-sound-panel" id="focus-sound-panel" hidden><div class="focus-sound-panel-heading"><div><span class="section-label">PAISAJE SONORO</span><h4>Encontrá tu ambiente.</h4></div><span class="focus-sound-frequency">AUDIO / 01</span></div><p class="focus-sound-description">Sonidos generados en el navegador. Reproducí uno para acompañar tu sesión, sin anuncios ni pistas externas.</p><div class="focus-sound-options"><button type="button" class="focus-sound-option" data-action="ambient-rain" data-ambient-sound="rain" aria-pressed="false"><span class="focus-sound-icon">⌁</span><span class="focus-sound-option-copy"><strong>Lluvia en la ciudad</strong><small>Lluvia suave y rumor urbano</small></span><span class="focus-sound-play">▶</span></button><button type="button" class="focus-sound-option" data-action="ambient-cafe" data-ambient-sound="cafe" aria-pressed="false"><span class="focus-sound-icon">☕</span><span class="focus-sound-option-copy"><strong>Cafetería</strong><small>Murmullos y ambiente cálido</small></span><span class="focus-sound-play">▶</span></button><button type="button" class="focus-sound-option" data-action="ambient-white" data-ambient-sound="white" aria-pressed="false"><span class="focus-sound-icon">≋</span><span class="focus-sound-option-copy"><strong>Ruido Blanco</strong><small>Un fondo constante y uniforme</small></span><span class="focus-sound-play">▶</span></button></div><div class="focus-audio-footer"><span class="focus-audio-status-dot" id="focus-audio-status-dot"></span><span id="ambient-status" role="status" aria-live="polite">Elegí un ambiente para reproducir.</span><button type="button" class="focus-audio-stop" id="ambient-stop" data-action="ambient-stop" hidden>Detener</button></div><p class="focus-audio-note">El audio solo empieza cuando lo activás. Podés pausarlo en cualquier momento.</p></aside></div><hr class="focus-station-divider"><p class="section-label">03 / TU ACTIVIDAD</p><div class="stats-row"><div><strong>${done}</strong><span>tareas listas</span></div><div><strong>${state.favorites.length}</strong><span>favoritos</span></div><div><strong>${state.points}</strong><span>puntos</span></div></div><button class="btn btn-outline btn-full" data-action="export-data">Exportar copia JSON ↗</button><label class="field" style="margin-top:14px">Restaurar una copia<input type="file" id="import-file" accept="application/json,.json"></label><p class="muted" style="line-height:1.6;margin-top:9px">Tus datos se guardan en este navegador. Exportá una copia si querés conservarlos o moverlos a otro equipo.</p></article></div></section>`;wireTasks();wireTimer();wireBackup()}
function renderSettings(){const taskCount=state.tasks.length,moduleCount=state.learningDone.length,reminders=state.reminderSettings||defaultState.reminderSettings;viewRoot.innerHTML=`<section class="page-content settings-page"><div class="content-heading"><div><p class="eyebrow">NEXO / PRIVACIDAD Y CUENTA</p><h2>Tus datos, tus decisiones.</h2><p>Podés usar NEXO sin cuenta: tus datos quedan en este navegador. Si conectás Supabase, también podés optar por una copia privada manual para otros dispositivos.</p></div><span class="agenda-date">CUENTA LOCAL</span></div><div class="settings-grid"><article class="tool-panel settings-panel"><p class="section-label">01 / TU INFORMACIÓN</p><h3>Una copia siempre a mano.</h3><p class="settings-description">Exportá tareas, agenda, bienestar, favoritos, récords y progreso de aprendizaje. El archivo JSON es tuyo.</p><div class="settings-stats"><div><strong>${taskCount}</strong><span>tareas</span></div><div><strong>${state.favorites.length}</strong><span>favoritos</span></div><div><strong>${Number(state.points)||0}</strong><span>puntos</span></div><div><strong>${moduleCount}</strong><span>módulos</span></div></div><button class="btn btn-dark btn-full" data-action="export-data">Exportar mis datos (.json) ↗</button><label class="btn btn-outline btn-full settings-import-label" for="import-file">Importar datos (.json) ↗</label><input class="settings-import-input" type="file" id="import-file" accept="application/json,.json"><p class="settings-note">Importar reemplaza los datos principales actuales. Exportá una copia antes para poder volver atrás.</p><p class="settings-storage-status" id="settings-storage-status" role="status" aria-live="polite">Comprobando opciones de almacenamiento…</p></article><article class="tool-panel settings-panel"><p class="section-label">02 / PRIVACIDAD REAL</p><h3>Vos tenés el control.</h3><div class="settings-privacy-list"><p><span aria-hidden="true">✓</span><span><strong>Por defecto, tus datos son locales.</strong><br>Agenda, progreso y registros no se envían automáticamente. La copia en nube es opcional y requiere consentimiento.</span></p><p><span aria-hidden="true">✓</span><span><strong>Recuperación local.</strong><br>NEXO guarda una copia auxiliar y usa IndexedDB cuando el navegador lo permite.</span></p><p><span aria-hidden="true">!</span><span><strong>Un límite importante.</strong><br>Si borrás todos los datos del sitio o cambiás de dispositivo, la copia local también puede desaparecer. El archivo exportado es el respaldo más confiable.</span></p></div><button class="btn btn-outline btn-full" data-action="start-tour">Volver a ver el recorrido ↗</button><button class="btn btn-quiet btn-full" data-action="reset">Borrar mis datos de este dispositivo</button></article><article class="tool-panel settings-panel reminders-panel"><p class="section-label">03 / RECORDATORIOS AMABLES</p><h3>Una pausa, si te sirve.</h3><p class="settings-description">Elegí avisos discretos si llevás tiempo sin interactuar. Sin puntos, rachas obligatorias ni castigos.</p><label class="field" for="reminder-interval">Avisar tras un rato sin actividad<select id="reminder-interval"><option value="60" ${Number(reminders.intervalMinutes)===60?'selected':''}>1 hora</option><option value="120" ${Number(reminders.intervalMinutes)===120?'selected':''}>2 horas</option><option value="180" ${Number(reminders.intervalMinutes)===180?'selected':''}>3 horas</option></select></label><p class="settings-note">Funciona mientras NEXO está abierto y la pestaña activa. No son notificaciones push cuando la app está cerrada.</p><button class="btn ${reminders.enabled?'btn-outline':'btn-dark'} btn-full" data-action="toggle-reminders">${reminders.enabled?'Desactivar recordatorios':'Activar recordatorios en este dispositivo'}</button><p class="settings-storage-status" id="reminders-status" role="status" aria-live="polite">${reminders.enabled?'Recordatorios activados.':'Recordatorios desactivados.'}</p></article><article class="tool-panel settings-panel cloud-sync-panel" id="nexo-cloud-sync-panel"><p class="section-label">04 / COPIA PRIVADA EN LA NUBE</p><h3>Tu NEXO, en tus dispositivos.</h3><p class="settings-description">La nube es opcional. NEXO sólo lee o sube una copia cuando marcás el consentimiento y pulsás un botón. No hay sincronización automática ni combinación silenciosa de cambios.</p><div class="cloud-sync-consent"><label for="nexo-cloud-consent"><input type="checkbox" id="nexo-cloud-consent"><span><strong>Quiero usar la copia privada en Supabase.</strong><br>Entiendo que la copia puede incluir tareas, notas, preferencias, bienestar y reflexiones guardadas. Sólo se accede al contenido después de marcar esta casilla y usar los controles.</span></label></div><div class="cloud-sync-actions"><button type="button" class="btn btn-outline" data-cloud-action="review" disabled>Revisar copia</button><button type="button" class="btn btn-dark" data-cloud-action="upload" disabled>Guardar copia local en la nube</button><button type="button" class="btn btn-outline" data-cloud-action="download" disabled>Restaurar nube en este dispositivo</button></div><p class="cloud-sync-warning">Importante: restaurar reemplaza los datos locales incluidos en la copia. Exportá un JSON antes de restaurar. Subir una copia distinta reemplaza la copia de nube completa; los conflictos de versión detienen el guardado en vez de sobrescribirlos.</p><p class="cloud-sync-status" id="nexo-cloud-sync-status" role="status" aria-live="polite">La copia no se consulta hasta que configures Supabase, inicies sesión y marques el consentimiento.</p></article></div></section>`;wireBackup();const status=document.querySelector('#settings-storage-status');if(status)status.textContent=window.NexoStore?'Respaldo en localStorage + copia auxiliar e IndexedDB; la persistencia depende del navegador.':'Almacenamiento básico disponible. Exportá una copia periódica.';window.NexoCloudSync?.mount()}
let taskFilter='all';
function wireTasks(){document.querySelector('#task-form').addEventListener('submit',e=>{e.preventDefault();const title=document.querySelector('#task-title').value.trim();if(!title)return;state.tasks.unshift({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),title,date:document.querySelector('#task-date').value,type:document.querySelector('#task-type').value,done:false,created:Date.now()});save();renderProgress();notify('Tarea agregada')});document.querySelectorAll('[data-task-filter]').forEach(b=>b.addEventListener('click',()=>{taskFilter=b.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(x=>x.classList.toggle('active',x===b));renderTaskList()}));renderTaskList()}
function renderTaskList(){const root=document.querySelector('#task-list');if(!root)return;const tasks=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));root.innerHTML=tasks.length?tasks.map(t=>`<div class="item-row"><input type="checkbox" class="check" data-task-check="${escapeHTML(t.id)}" ${t.done?'checked':''} aria-label="Completar tarea"><div class="item-main"><strong style="${t.done?'text-decoration:line-through;opacity:.6':''}">${escapeHTML(t.title)}</strong><small>${escapeHTML(t.type)}${t.date?' · '+escapeHTML(t.date):''}</small></div><button data-task-edit="${escapeHTML(t.id)}">Editar</button><button data-task-delete="${escapeHTML(t.id)}" aria-label="Eliminar tarea">×</button></div>`).join(''):'<div class="empty-state">Todavía no hay tareas en esta vista. Podés empezar con algo pequeño.</div>';root.querySelectorAll('[data-task-check]').forEach(el=>el.addEventListener('change',()=>{const t=state.tasks.find(x=>x.id===el.dataset.taskCheck);if(t&&!t.done&&el.checked){state.points+=3;recordGentleHabit('task')}if(t)t.done=el.checked;save();renderProgress();notify(el.checked?'Tarea completada. ¡Bien ahí!':'Tarea reabierta')}));root.querySelectorAll('[data-task-delete]').forEach(el=>el.addEventListener('click',()=>{state.tasks=state.tasks.filter(t=>t.id!==el.dataset.taskDelete);save();renderProgress();notify('Tarea eliminada')}));root.querySelectorAll('[data-task-edit]').forEach(el=>el.addEventListener('click',()=>{const t=state.tasks.find(x=>x.id===el.dataset.taskEdit);if(!t)return;const val=prompt('Editar tarea:',t.title);if(val===null)return;if(!val.trim()){notify('El título no puede quedar vacío');return}t.title=val.trim().slice(0,120);save();renderTaskList();notify('Tarea actualizada')}))}
let timerInterval=null,timerRemaining=1500,timerTotal=1500,timerHasStarted=false,timerCompleted=false;
const FOCUS_RING_CIRCUMFERENCE=540.35;
let ambientAudioContext=null,ambientActiveSound='',ambientNodes=[],ambientIntervals=[];
function paintFocusTimer(statusOverride){
 const display=document.querySelector('#timer-display'),status=document.querySelector('#timer-status'),duration=document.querySelector('#timer-duration'),ring=document.querySelector('#timer-ring-progress'),shell=document.querySelector('#focus-clock-shell'),start=document.querySelector('#timer-start'),station=document.querySelector('#focus-station-card');
 if(display)display.textContent=String(Math.floor(Math.max(0,timerRemaining)/60)).padStart(2,'0')+':'+String(Math.max(0,timerRemaining)%60).padStart(2,'0');
 const ratio=timerTotal>0?Math.max(0,Math.min(1,timerRemaining/timerTotal)):0;
 if(ring)ring.setAttribute('stroke-dashoffset',String(FOCUS_RING_CIRCUMFERENCE*(1-ratio)));
 if(shell){shell.setAttribute('aria-valuenow',String(Math.round(ratio*100)));shell.setAttribute('aria-valuetext',Math.ceil(Math.max(0,timerRemaining)/60)+' minutos restantes')}
 if(status)status.textContent=statusOverride||(timerInterval?'SESIÓN EN CURSO · UN PASO A LA VEZ':timerCompleted?'SESIÓN COMPLETADA. ¡BIEN HECHO!':timerHasStarted?'SESIÓN EN PAUSA · CONTINUÁ CUANDO QUIERAS':'LISTO CUANDO VOS ESTÉS');
 if(start)start.textContent=timerInterval?'Pausar':timerCompleted?'Otra sesión':timerHasStarted?'Continuar':'Empezar';
 if(station)station.classList.toggle('is-running',Boolean(timerInterval));
 if(duration&&String(timerTotal/60)!==duration.value)duration.value=String(timerTotal/60);
}
function wireTimer(){
 const duration=document.querySelector('#timer-duration'),start=document.querySelector('#timer-start'),reset=document.querySelector('#timer-reset');
 if(!duration||!start||!reset)return;
 duration.value=String(timerTotal/60);paintFocusTimer();
 duration.addEventListener('change',()=>{
  stopTimer();timerTotal=Number(duration.value)*60;timerRemaining=timerTotal;timerHasStarted=false;timerCompleted=false;stopAmbientSound(false);paintFocusTimer('Duración actualizada. Empezá cuando estés listo.');
 });
 start.addEventListener('click',()=>{
  if(timerInterval){stopTimer();paintFocusTimer('Sesión en pausa. Podés continuar cuando quieras.');return}
  if(timerCompleted||timerRemaining<=0){timerRemaining=timerTotal;timerCompleted=false;timerHasStarted=false}
  timerHasStarted=true;timerInterval=setInterval(focusTimerTick,1000);paintFocusTimer('MODO ENFOQUE ACTIVADO · TOMÁ UN RESPIRO CUANDO TERMINE');
 });
 reset.addEventListener('click',()=>{
  stopTimer();timerRemaining=timerTotal;timerHasStarted=false;timerCompleted=false;stopAmbientSound(false);paintFocusTimer('Temporizador reiniciado.');notify('Bloque reiniciado.');
 });
 syncAmbientUI();
}
function focusTimerTick(){
 if(!timerInterval)return;
 timerRemaining=Math.max(0,timerRemaining-1);
 if(timerRemaining<=0){
  clearInterval(timerInterval);timerInterval=null;timerRemaining=0;timerCompleted=true;
  state.points+=5;state.focusSessions=(state.focusSessions||0)+1;recordGentleHabit('focus');save();updateStats();stopAmbientSound(false);
  paintFocusTimer('SESIÓN COMPLETADA. ¡BIEN HECHO!');notify('Terminaste tu bloque de enfoque. Sumaste 5 puntos NEXO.');
  return;
 }
 paintFocusTimer();
}
function stopTimer(){if(timerInterval)clearInterval(timerInterval);timerInterval=null;paintFocusTimer()}
function createFocusNoiseBuffer(context,color='pink'){
 const length=context.sampleRate*4,buffer=context.createBuffer(1,length,context.sampleRate),data=buffer.getChannelData(0);
 let brown=0,pinkA=0,pinkB=0;
 for(let i=0;i<length;i++){const white=Math.random()*2-1;brown=(brown+0.018*white)/1.018;pinkA=.985*pinkA+.015*white;pinkB=.91*pinkB+.09*white;data[i]=color==='white'?white:color==='brown'?brown*4:(pinkA*.7+pinkB*.3)*2.2}
 return buffer;
}
function connectFocusNoise(context,buffer,master,{filter='lowpass',frequency=2800,q=.7,gain=.3,highpass=0}={}){
 const source=context.createBufferSource(),filterNode=context.createBiquadFilter(),gainNode=context.createGain();
 source.buffer=buffer;source.loop=true;filterNode.type=filter;filterNode.frequency.value=frequency;filterNode.Q.value=q;gainNode.gain.value=gain;
 if(highpass){const high=context.createBiquadFilter();high.type='highpass';high.frequency.value=highpass;source.connect(high);high.connect(filterNode);ambientNodes.push(high)}else source.connect(filterNode);
 filterNode.connect(gainNode);gainNode.connect(master);source.start();ambientNodes.push(source,filterNode,gainNode);return gainNode;
}
async function startAmbientSound(kind){
 if(ambientActiveSound===kind){stopAmbientSound();return}
 stopAmbientSound(false);const AudioContextClass=window.AudioContext||window.webkitAudioContext;
 if(!AudioContextClass){updateAmbientUI('Este navegador no permite reproducir audio ambiental.',true);return}
 try{
  const context=new AudioContextClass();ambientAudioContext=context;await context.resume();
  const master=context.createGain();master.gain.value=.2;master.connect(context.destination);ambientNodes.push(master);
  if(kind==='rain'){
   const pink=createFocusNoiseBuffer(context,'pink'),brown=createFocusNoiseBuffer(context,'brown');
   connectFocusNoise(context,pink,master,{filter:'lowpass',frequency:4400,gain:.42,highpass:260});
   connectFocusNoise(context,brown,master,{filter:'lowpass',frequency:520,gain:.34,highpass:55});
   ambientIntervals.push(setInterval(()=>{
    if(!ambientAudioContext||ambientAudioContext!==context||context.state==='closed')return;
    const osc=context.createOscillator(),filter=context.createBiquadFilter(),gain=context.createGain(),now=context.currentTime;
    osc.type='sine';osc.frequency.value=950+Math.random()*1750;filter.type='bandpass';filter.frequency.value=1400+Math.random()*2000;filter.Q.value=2.5;
    gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.025+Math.random()*.015,now+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+.12+Math.random()*.08);
    osc.connect(filter);filter.connect(gain);gain.connect(master);osc.onended=()=>{try{osc.disconnect();filter.disconnect();gain.disconnect()}catch{}};osc.start(now);osc.stop(now+.24);
   },450));
  }else if(kind==='cafe'){
   const pink=createFocusNoiseBuffer(context,'pink'),brown=createFocusNoiseBuffer(context,'brown');
   const murmur=connectFocusNoise(context,pink,master,{filter:'bandpass',frequency:620,q:.55,gain:.34,highpass:170});
   connectFocusNoise(context,brown,master,{filter:'lowpass',frequency:1250,q:.45,gain:.28,highpass:70});
   const lfo=context.createOscillator(),depth=context.createGain();lfo.type='sine';lfo.frequency.value=.09;depth.gain.value=.055;lfo.connect(depth);depth.connect(murmur.gain);lfo.start();ambientNodes.push(lfo,depth);
   ambientIntervals.push(setInterval(()=>{
    if(!ambientAudioContext||ambientAudioContext!==context||context.state==='closed')return;
    if(Math.random()>.55)return;
    const osc=context.createOscillator(),gain=context.createGain(),now=context.currentTime;
    osc.type='sine';osc.frequency.value=1100+Math.random()*900;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.012,now+.018);gain.gain.exponentialRampToValueAtTime(.0001,now+.33);
    osc.connect(gain);gain.connect(master);osc.onended=()=>{try{osc.disconnect();gain.disconnect()}catch{}};osc.start(now);osc.stop(now+.36);
   },3600));
  }else{
   const white=createFocusNoiseBuffer(context,'white');connectFocusNoise(context,white,master,{filter:'lowpass',frequency:7000,gain:.47,highpass:90});
  }
  ambientActiveSound=kind;syncAmbientUI();
 }catch(error){stopAmbientSound(false);updateAmbientUI('No se pudo iniciar el audio. Probá de nuevo.',true)}
}
function updateAmbientUI(message,isError=false){
 const status=document.querySelector('#ambient-status'),dot=document.querySelector('#focus-audio-status-dot'),stop=document.querySelector('#ambient-stop');
 if(status&&message)status.textContent=message;if(status)status.classList.toggle('is-error',Boolean(isError));if(dot)dot.classList.toggle('is-playing',Boolean(ambientActiveSound));if(stop)stop.hidden=!ambientActiveSound;
}
function syncAmbientUI(){
 const names={rain:'Lluvia en la ciudad',cafe:'Cafetería',white:'Ruido Blanco'};
 document.querySelectorAll('[data-ambient-sound]').forEach(button=>{const active=button.dataset.ambientSound===ambientActiveSound;button.classList.toggle('is-playing',active);button.setAttribute('aria-pressed',String(active));const icon=button.querySelector('.focus-sound-play');if(icon)icon.textContent=active?'Ⅱ':'▶'});
 updateAmbientUI(ambientActiveSound?'Reproduciendo: '+names[ambientActiveSound]+'.':'Elegí un ambiente para reproducir.');
}
function stopAmbientSound(showMessage=true){
 ambientIntervals.forEach(id=>clearInterval(id));ambientIntervals=[];const context=ambientAudioContext;ambientAudioContext=null;
 ambientNodes.forEach(node=>{try{if(typeof node.stop==='function')node.stop()}catch{}try{node.disconnect()}catch{}});ambientNodes=[];
 if(context&&context.state!=='closed')context.close().catch(()=>{});
 ambientActiveSound='';syncAmbientUI();if(showMessage)updateAmbientUI('Audio detenido.');
}
