 if(!panel||!toggle)return;const open=panel.hidden;panel.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.querySelector('.focus-sound-toggle-label').textContent=open?'Ocultar paisaje sonoro':'Abrir paisaje sonoro';toggle.querySelector('.focus-sound-toggle-arrow').textContent=open?'−':'＋';if(layout)layout.classList.toggle('has-sounds-open',open);
 if(open)panel.querySelector('button:not([hidden])')?.focus({preventScroll:true});
