function wireBackup(){document.querySelector('#import-file')?.addEventListener('change',importData)}
function exportData(){const local={};for(const key of [WELLBEING_HOME_KEY,REFLEX_STORAGE_KEY,DISCOVERY_DAILY_KEY,COMPANION_WEEKLY_KEY,COMPANION_REFLECTION_KEY]){const value=readLocal(key);if(value!==null&&value!==undefined)local[key]=value}const payload={product:'NEXO',version:2,exportedAt:new Date().toISOString(),state,local};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='nexo-copia-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);notify('Tu copia JSON está lista. Guardala en un lugar seguro.')}
function importData(event){const file=event.target.files?.[0];if(!file)return;if(file.size>2000000){notify('El archivo supera el límite de 2 MB.');event.target.value='';return}const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(String(reader.result||'')),incoming=parsed.state||parsed;if(!incoming||!Array.isArray(incoming.tasks)||!Array.isArray(incoming.favorites))throw Error('formato');const validLocal={},allow=[WELLBEING_HOME_KEY,REFLEX_STORAGE_KEY,DISCOVERY_DAILY_KEY,COMPANION_WEEKLY_KEY,COMPANION_REFLECTION_KEY];for(const key of allow){const raw=parsed.local&&parsed.local[key];if(typeof raw!=='string')continue;const value=JSON.parse(raw);if(key===WELLBEING_HOME_KEY&&(!value||typeof value.date!=='string'||!Number.isFinite(Number(value.water))))throw Error('agua');if(key===REFLEX_STORAGE_KEY&&(!Array.isArray(value)||!value.every(n=>Number.isFinite(n)&&n>0)))throw Error('récord');if(key===DISCOVERY_DAILY_KEY&&(!value||typeof value.day!=='string'||!Array.isArray(value.ids)||!value.ids.every(id=>typeof id==='string')))throw Error('historial');if(key===COMPANION_WEEKLY_KEY&&(!value||typeof value.weekStart!=='string'||typeof value.foodNote!=='string'||typeof value.physicalNote!=='string'||value.foodNote.length>320||value.physicalNote.length>320))throw Error('ruta');if(key===COMPANION_REFLECTION_KEY&&(!value||typeof value.text!=='string'||value.text.length>1400||!['ai','local'].includes(value.source)))throw Error('reflejo');validLocal[key]=raw}state=normalizeState(incoming);if(!save())throw Error('guardado');Object.entries(validLocal).forEach(([key,value])=>writeLocal(key,value));setTheme();setView(currentView);updateStats();notify('Copia restaurada. Tus datos principales ya están disponibles.')}catch{notify('La copia no es válida o no se pudo guardar.')}finally{event.target.value=''}};reader.readAsText(file)}
/* Expose only validated, explicit snapshots to the opt-in cloud-sync module. */
function validateSyncLocalValue(key, raw) {
 if(typeof raw!=='string'||raw.length>300000)return false;
 let value;
 try{value=JSON.parse(raw)}catch{return false}
 if(key===WELLBEING_HOME_KEY)return Boolean(value&&typeof value.date==='string'&&Number.isFinite(Number(value.water)));
 if(key===REFLEX_STORAGE_KEY)return Array.isArray(value)&&value.every(n=>Number.isFinite(n)&&n>0);
 if(key===DISCOVERY_DAILY_KEY)return Boolean(value&&typeof value.day==='string'&&Array.isArray(value.ids)&&value.ids.every(id=>typeof id==='string'));
 if(key===COMPANION_WEEKLY_KEY)return Boolean(value&&typeof value.weekStart==='string'&&typeof value.foodNote==='string'&&typeof value.physicalNote==='string'&&value.foodNote.length<=320&&value.physicalNote.length<=320);
 if(key===COMPANION_REFLECTION_KEY)return Boolean(value&&typeof value.text==='string'&&value.text.length<=1400&&['ai','local'].includes(value.source));
 return false;
}
function getNexoSyncSnapshot(){
 const local={};
 for(const key of [WELLBEING_HOME_KEY,REFLEX_STORAGE_KEY,DISCOVERY_DAILY_KEY,COMPANION_WEEKLY_KEY,COMPANION_REFLECTION_KEY]){
  const raw=readLocal(key);
  if(raw!==null&&raw!==undefined){
   if(typeof raw!=='string'||!validateSyncLocalValue(key,raw))throw new Error('Un registro local auxiliar tiene un formato inesperado. Exportá una copia JSON antes de sincronizar.');
   local[key]=raw;
  }
 }
 return {product:'NEXO',schemaVersion:1,state:JSON.parse(JSON.stringify(state)),local};
}
function applyNexoSyncSnapshot(snapshot){
 const allowed=[WELLBEING_HOME_KEY,REFLEX_STORAGE_KEY,DISCOVERY_DAILY_KEY,COMPANION_WEEKLY_KEY,COMPANION_REFLECTION_KEY];
 if(!snapshot||snapshot.product!=='NEXO'||snapshot.schemaVersion!==1||!snapshot.state||typeof snapshot.state!=='object'||Array.isArray(snapshot.state)||!Array.isArray(snapshot.state.tasks)||!Array.isArray(snapshot.state.favorites)||!snapshot.local||typeof snapshot.local!=='object'||Array.isArray(snapshot.local))return false;
 const incomingLocal={};
 for(const key of Object.keys(snapshot.local)){
  if(!allowed.includes(key)||!validateSyncLocalValue(key,snapshot.local[key]))return false;
  incomingLocal[key]=snapshot.local[key];
 }
 let previousState;
 try{previousState=JSON.parse(JSON.stringify(state))}catch{return false}
 const previousLocal={};
 for(const key of allowed)previousLocal[key]=readLocal(key);
 state=normalizeState(snapshot.state);
 if(!save()){state=normalizeState(previousState);save();return false}
 for(const key of allowed){
  if(Object.prototype.hasOwnProperty.call(incomingLocal,key)){
   if(!writeLocal(key,incomingLocal[key])){
    state=normalizeState(previousState);save();
    for(const oldKey of allowed){const raw=previousLocal[oldKey];if(typeof raw==='string')writeLocal(oldKey,raw);else removeLocal(oldKey)}
    setTheme();updateStats();setView(currentView);return false
   }
  }else removeLocal(key);
 }
 setTheme();updateStats();setView(currentView);
 return true;
}
window.NexoAppData=Object.freeze({getSnapshot:getNexoSyncSnapshot,applySnapshot:applyNexoSyncSnapshot});
