let gentleReminderTicker=null,lastGentleInteractionAt=Date.now();
function startGentleReminderService(){if(gentleReminderTicker)return;const resetActivity=()=>{lastGentleInteractionAt=Date.now()};['pointerdown','keydown','input','touchstart'].forEach(eventName=>document.addEventListener(eventName,resetActivity,{passive:true}));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')lastGentleInteractionAt=Date.now()});gentleReminderTicker=window.setInterval(()=>{const prefs=state.reminderSettings||defaultState.reminderSettings;if(!prefs.enabled||document.visibilityState!=='visible')return;const interval=Math.max(60,Math.min(180,Number(prefs.intervalMinutes)||120))*60000;if(Date.now()-lastGentleInteractionAt<interval)return;lastGentleInteractionAt=Date.now();prefs.lastReminderAt=Date.now();const message='¿Te viene bien una pausa, un vaso de agua o cerrar NEXO por un rato? Vos elegís.';let shown=false;try{if('Notification'in window&&Notification.permission==='granted'){new Notification('NEXO · A tu ritmo',{body:message,tag:'nexo-gentle-reminder'});shown=true}}catch{}if(!shown)notify(message);save()},60000)}
async function toggleGentleReminders(){const prefs=state.reminderSettings||(state.reminderSettings={...defaultState.reminderSettings});if(prefs.enabled){prefs.enabled=false;save();renderSettings();notify('Recordatorios desactivados.');return}prefs.intervalMinutes=[60,120,180].includes(Number(document.querySelector('#reminder-interval')?.value))?Number(document.querySelector('#reminder-interval').value):120;let granted=false;try{if('Notification'in window){let permission=Notification.permission;if(permission==='default')permission=await Notification.requestPermission();granted=permission==='granted'}}catch{}prefs.enabled=true;prefs.lastReminderAt=Date.now();lastGentleInteractionAt=Date.now();save();renderSettings();notify(granted?'Recordatorios amables activados en este dispositivo.':'Avisos dentro de NEXO activados; el navegador no autorizó notificaciones del sistema.');}
document.addEventListener('click',e=>{const briefRead=e.target.closest('[data-action="world-brief-read"]');if(briefRead){openWorldBriefSummary(Number(briefRead.dataset.briefIndex));return}const briefAction=e.target.closest('[data-action]')?.dataset.action;if(briefAction==='world-brief-close'){document.querySelector('#world-brief-dialog')?.close();return}if(briefAction==='world-brief-prev'||briefAction==='world-brief-next'){rotateWorldBrief(briefAction==='world-brief-next'?1:-1);return}const memeCard=e.target.closest('[data-meme-url]');if(memeCard){selectMemeTemplate(memeCard.dataset.memeUrl,memeCard.dataset.memeName||'Plantilla');return}const memeQuery=e.target.closest('[data-meme-query]');if(memeQuery){const input=document.querySelector('#meme-search');if(input)input.value=memeQuery.dataset.memeQuery;memeSearchTerm=memeQuery.dataset.memeQuery;renderMemeResults();return}const healthStep=e.target.closest('[data-health-step]');if(healthStep){adjustWellness(healthStep);return}const del=e.target.closest('[data-goal-delete]');if(del){state.goals.splice(Number(del.dataset.goalDelete),1);save();renderGoals();return}const preset=e.target.closest('[data-focus-min]');if(preset){stopFocus();focusTotal=focusRemaining=Number(preset.dataset.focusMin)*60;document.querySelectorAll('[data-focus-min]').forEach(b=>b.classList.toggle('active',b===preset));const l=document.querySelector('#focus-label');if(l)l.textContent='MINUTOS PARA VOS';paintFocus();return}const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);if(nav.closest('#mobile-menu-panel'))setMobileMenuOpen(false);return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;switch(action){case'surprise':surprise();break;case'start-tour':startOnboarding(true);break;case'discovery-swipe-left':swipeDiscoveryByAction('left');break;case'discovery-swipe-right':swipeDiscoveryByAction('right');break;case'discovery-replay':startDiscoveryDeck(true);break;case'toggle-deep-mode':setDeepMode(!deepModeActive);break;case'toggle-focus-sounds':toggleFocusSoundPanel();break;case'ambient-rain':startAmbientSound('rain');break;case'ambient-cafe':startAmbientSound('cafe');break;case'ambient-white':startAmbientSound('white');break;case'ambient-stop':stopAmbientSound();break;case'neural-release':releaseNeuralText();break;case'neural-clear':clearNeuralText();break;case'new-prompt':document.querySelector('#daily-text').textContent=prompts[Math.floor(Math.random()*prompts.length)];break;case'reset':document.querySelector('#confirm-dialog').showModal();break;case'generate-idea':generateIdea();break;case'copy-idea':navigator.clipboard?.writeText(document.querySelector('#idea-result')?.textContent||'').then(()=>notify('Texto copiado')).catch(()=>notify('Seleccioná y copiá el texto manualmente'));break;case'generate-character':generateCharacter();break;case'download-meme':{const c=document.querySelector('#meme-canvas');if(c){try{const a=document.createElement('a');a.download='nexo-meme.png';a.href=c.toDataURL('image/png');a.click();state.created++;save();notify('Tu meme se descargó como PNG')}catch(err){notify('Ese fondo no permite exportación directa. Elegí otra plantilla o usá el fondo gráfico.')}}break}case'random-meme':if(memeTemplates.length){const pool=memeTemplates.filter(m=>m.url!==memeImage?.src);const choice=pool[Math.floor(Math.random()*Math.max(1,pool.length))]||memeTemplates[0];selectMemeTemplate(choice.url,choice.name)}else{memeBg++;memeImage=null;drawMeme();loadMemeTemplates()}break;case'surprise-meme':surpriseMeme();break;case'surprise-discovery':surpriseDiscovery();break;case'start-quiz':startQuiz();break;case'start-word':startWord();break;case'toggle-reflex':{const panel=document.querySelector('#reflex-game'),toggle=document.querySelector('[data-action="toggle-reflex"]');if(panel&&toggle){const opening=panel.hidden;panel.hidden=!opening;toggle.setAttribute('aria-expanded',String(opening));toggle.querySelector('.reflex-expand-icon').textContent=opening?'−':'＋';if(opening)setupReflexGame();else stopReflexTimers()}break}case'reflex-start':startReflexRound();break;case'reflex-target':handleReflexTap();break;case'export-data':exportData();break;case'toggle-reminders':toggleGentleReminders();break;case'companion-save-checkin':saveCompanionWeeklyCheckin();break;case'companion-reflect':runCompanionAction('reflection');break;case'companion-suggestion':runCompanionAction('suggestion');break;case'focus-start':startFocus();break;case'focus-pause':stopFocus();notify('Temporizador en pausa.');break;case'focus-reset':setupFocus();break;case'save-notes':saveNotes();break;case'save-reflection':saveReflection();break;case'wellness-step':adjustWellness(e.target.closest('[data-health-step]'));break;case'wellness-save':saveWellness();break;case'wellness-reset':resetWellnessToday();break;case'learning-reset':resetLearning();break}});
document.querySelector('#theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();setTheme()});document.querySelector('#mobile-theme').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';save();setTheme()});document.querySelector('#mobile-menu-toggle')?.addEventListener('click',()=>setMobileMenuOpen(document.querySelector('#mobile-menu-toggle').getAttribute('aria-expanded')!=='true'));document.addEventListener('click',event=>{if(!event.target.closest('.mobile-nav'))setMobileMenuOpen(false)});document.querySelector('#confirm-reset').addEventListener('click',e=>{e.preventDefault();document.querySelector('#confirm-dialog').close();resetAll()});document.querySelector('#profile-button').addEventListener('click',()=>setView('ajustes'));
document.querySelector('#global-search').addEventListener('keydown',e=>{if(e.key!=='Enter')return;const q=e.target.value.trim().toLowerCase();if(!q)return;const d=discoveries.find(item=>(item.title+' '+item.text+' '+item.category).toLowerCase().includes(q));if(d){setView('descubrir');setTimeout(()=>{if(currentView!=='descubrir')return;discoveryDeckQueue=[d,...discoveryDeckQueue.filter(item=>item.id!==d.id)];renderDiscoveryCards()},0)}else if(['meme','crear','idea','frase'].some(k=>q.includes(k)))setView('crear');else if(['juego','trivia','palabra'].some(k=>q.includes(k)))setView('jugar');else if(['tarea','progreso','enfoque','agenda','organizar'].some(k=>q.includes(k)))setView('progreso');else if(['salud','bienestar','movimiento','descanso','agua','sueño'].some(k=>q.includes(k)))setView('bienestar');else if(['aprender','estudiar','html','css','javascript','ciencia'].some(k=>q.includes(k)))setView('aprender');else if(['profundo','deep mode','descompresor','neural','soltar'].some(k=>q.includes(k)))setView('neural');else setView('descubrir')});
const ONBOARDING_KEY='nexo-onboarding-v1';
let onboardingOverlay=null,onboardingStep=0,onboardingResizeHandler=null;
function setMobileMenuOpen(open){const panel=document.querySelector('#mobile-menu-panel'),toggle=document.querySelector('#mobile-menu-toggle');if(!panel||!toggle)return;const show=Boolean(open)&&window.matchMedia('(max-width: 700px)').matches;panel.classList.toggle('is-open',show);toggle.setAttribute('aria-expanded',String(show));toggle.classList.toggle('is-open',show)}
function onboardingSteps(){const mobile=window.matchMedia('(max-width: 700px)').matches;return [{target:mobile?'#mobile-menu-toggle':'.rail-nav',title:'Todo empieza por acá',body:'Este menú te lleva a crear, jugar, aprender y cuidar tu bienestar. No hay un orden obligatorio: elegí lo que te sirva hoy.'},{target:mobile?'#mobile-menu-panel [data-view="agenda"]':'.rail-nav [data-view="agenda"]',title:'Tu foco, a tu ritmo',body:'En Mi agenda tenés tus tareas y el temporizador de enfoque. Probá un bloque corto; pausar o cambiar de plan también está bien.'},{target:mobile?'.mobile-top .global-deep-switch':'.rail-bottom .global-deep-switch',title:'Un espacio con menos ruido',body:'El Modo Profundo cambia la interfaz y abre el Descompresor Neural para escribir en privado. Ese texto efímero no se guarda ni se envía.'}]}
function finishOnboarding(markDone=true){if(onboardingOverlay){onboardingOverlay.remove();onboardingOverlay=null}if(onboardingResizeHandler){window.removeEventListener('resize',onboardingResizeHandler);onboardingResizeHandler=null}document.removeEventListener('keydown',onboardingKeyHandler);setMobileMenuOpen(false);if(markDone)writeLocal(ONBOARDING_KEY,JSON.stringify('done'))}
function onboardingKeyHandler(event){if(!onboardingOverlay)return;if(event.key==='Escape'){finishOnboarding(true);return}if(event.key==='Enter'&&event.target.closest('.tour-tooltip'))advanceOnboarding()}
function drawOnboardingStep(){if(!onboardingOverlay)return;const steps=onboardingSteps(),step=steps[onboardingStep],mobile=window.matchMedia('(max-width: 700px)').matches;if(!step){finishOnboarding(true);return}if(mobile&&onboardingStep===1)setMobileMenuOpen(true);else if(onboardingStep!==1)setMobileMenuOpen(false);const target=document.querySelector(step.target);if(!target){finishOnboarding(false);return}const rect=target.getBoundingClientRect(),highlight=onboardingOverlay.querySelector('.tour-highlight'),tooltip=onboardingOverlay.querySelector('.tour-tooltip');highlight.style.left=Math.max(4,rect.left-5)+'px';highlight.style.top=Math.max(4,rect.top-5)+'px';highlight.style.width=Math.max(1,rect.width+10)+'px';highlight.style.height=Math.max(1,rect.height+10)+'px';const width=Math.min(360,window.innerWidth-28),height=190,top=rect.bottom+height+15<window.innerHeight?rect.bottom+15:Math.max(12,rect.top-height-14),left=Math.max(14,Math.min(window.innerWidth-width-14,rect.left+rect.width/2-width/2));tooltip.style.width=width+'px';tooltip.style.left=left+'px';tooltip.style.top=top+'px';tooltip.querySelector('.tour-progress').textContent='PASO 0'+(onboardingStep+1)+' / 03';tooltip.querySelector('h2').textContent=step.title;tooltip.querySelector('.tour-copy').textContent=step.body;tooltip.querySelector('[data-tour-next]').textContent=onboardingStep===2?'Listo, vamos':'Siguiente →'}
function advanceOnboarding(){if(onboardingStep<2){onboardingStep++;drawOnboardingStep()}else finishOnboarding(true)}
function startOnboarding(force=false){if(!force&&readLocal(ONBOARDING_KEY)===JSON.stringify('done'))return;if(onboardingOverlay)onboardingOverlay.remove();setMobileMenuOpen(false);onboardingStep=0;onboardingOverlay=document.createElement('div');onboardingOverlay.className='tour-backdrop';onboardingOverlay.innerHTML='<div class="tour-highlight" aria-hidden="true"></div><section class="tour-tooltip" role="dialog" aria-modal="true" aria-labelledby="tour-title"><p class="tour-progress">PASO 01 / 03</p><h2 id="tour-title"></h2><p class="tour-copy"></p><div class="tour-actions"><button type="button" class="btn btn-quiet" data-tour-skip>Lo veo después</button><button type="button" class="btn btn-dark" data-tour-next>Siguiente →</button></div></section>';document.body.appendChild(onboardingOverlay);onboardingOverlay.querySelector('[data-tour-skip]').addEventListener('click',()=>finishOnboarding(true));onboardingOverlay.querySelector('[data-tour-next]').addEventListener('click',advanceOnboarding);onboardingResizeHandler=drawOnboardingStep;window.addEventListener('resize',onboardingResizeHandler,{passive:true});document.addEventListener('keydown',onboardingKeyHandler);drawOnboardingStep()}
function maybeStartOnboarding(){if(readLocal(ONBOARDING_KEY)===JSON.stringify('done'))return;window.setTimeout(()=>startOnboarding(false),550)}

function initializeHome(){const html=document.querySelector('#app-view').innerHTML;viewRoot.innerHTML=html;document.querySelector('#daily-text').textContent=prompts[Math.floor(Math.random()*prompts.length)];updateStats();setTheme()}
removeLocal('nexo-world-brief-gnews-key-v1');initializeHome();setupWorldBrief();initializeResilientStorage();startGentleReminderService();maybeStartOnboarding();
